const items0 = [["HG33-rfix2", () => "Appendix D: Anxiety \u2014 body first\n\nRemember that often the anxiety comes from a protector part of you, who is trying to help you, but who believes you are in danger, or may be shamed, or abandoned, or fail, or be exposed, or be sick, or be rejected, or lose control, or whatever. Therefore, instead of interrogating that part, start with yourself:\n\nAlways work with yourself in a series \u2013 first your body, then your inner child, then some inquiry, then some action:\n\nInner child love\n\nHere is some inner child love. Put your hand over your heart and your other hand on your solar plexis, and say to yourself in a loving way, \u201cLittle one, you are not alone. You don\u2019t have to fix this. I\u2019m here now. The adult is listening.\u201d Make sure you are actually talking to your inner child, who is scared to death.\n\nReduced breathing / Buteyko-style breathing\n\nThen work on your reduced breathing / Buteyko\u2019 breathing. (NOTE: there are some good things to be said for slowing your breathing down, if you are breathing too much, or panicked. However, please don\u2019t hold your breath until you are air hungry, which can make you more anxious in the short term. Go slow on this.) Inhale small amounts through your nose, exhale quietly through it, and pause only if comfortable. Can you make your breathing very quiet? If you feel bad, dizzy, or panicky, or have medical issues, STOP!\n\nEFT tapping\n\nEFT tapping: One of the easiest ways to do EFT is to say something like, \u201cEven though I have this anxiety, I am willing to be kind to the part of me that is afraid,\u201d while you tap gently on your body and stay with what you feel. There isn\u2019t a ton of evidence for EFT, but there are some studies on anxiety. A 2025 systematic review found 7 randomized control trials for anxiety disorders, and noted that EFT was more effective than no intervention in a few studies. So use the evidence with caution, and know that there are first line therapies for anxiety.\n\nSomatic Experiencing\n\nSomatic experiencing: If you would like more information about somatic experiencing, or even a free intro session, please see my somatic guide . In somatic experiencing (SE), you are not thrusting into the trauma. You learn to track. So you might start by tracking, by discovering where the activation is, where a neutral place is, and then whether you can move your attention from one to the other, very slowly, like a snail.\n\nGendlin Focusing\n\nGendlin Focusing: Focusing is another approach where you work with your body. You might say to yourself, \u201cWhat is the felt sense of this whole anxiety?\u201d Don\u2019t answer with your head; let your body come up with a vague sense of the whole anxiety. Then ask, \u201cWhat would this felt sense like me to know?\u201d Try a word or a phrase and see how well it fits the felt sense. But also see if what the word or phrase says is true of the situation. The word may feel ok, but say something that doesn\u2019t fit the situation, or vice versa. Use the words and the body to mutually correct one another.\n\nBody supports\n\nWork with the body. Sometimes the mind is too activated for meditation to help, so you may need to work directly with the body to calm it down. Maybe get a massage, or massage a foot, your scalp, a temple, or the back of the neck, the top of a shoulder, etc. (Avoid massaging the front of the neck. Also avoid massaging injured or numb body parts, or bruised, inflamed, or recently surgically operated on areas, or varicose veins. Also stop if the massage makes the anxiety symptoms worse, or makes you feel bad in any way, such as painful, dizzy, tingly, etc.) There are many other somatic approaches you can try, like heat, pressure, a weighted blanket, darkness, your favorite calming music, a careful use of a massage gun, etc.\n\nYou may find that you settle down with some of these things: warmth, darkness, favorite music, massage, a weighted blanket, some breathwork, a favorite object, technology you use to relax, etc.\n\nI have a page on my ZHoly3O product, which is ozonated charcoal, and I talk about this \u201choly water\u201d as one of the things that can help you relax. (See the mention of Blushield on that page, too.) But neither one of those products are necessary. All you really need is to stabilize yourself, and then listen to the messages from your inner realm, reality test those messages (neither product proves they are true), and then take one grounded action.\n\nA script you could use for anxiety is:\n\nAnxiety script\n\nWhere are my body parts? What are my feet doing? How is my body positioned in the chair? How is my body breathing? How is my body situated in the room?\n\nIf you\u2019re there little one, I\u2019m here. Thank you protector for letting me know you\u2019re here, you didn\u2019t have to scream I got your message.\n\nIf there is something we need to do let me know what the first thing is that we need to do at this moment, if there is nothing to do help my body stand down. I\u2019m not going to abandon you but I\u2019m not going to worship you, I will listen to what you have to say and reality test it and then take some action.", "67351cd828588fd5ce2b87fad8679c2bf272199169ce1220c07ee36dd66ae37e"], ["HG33-e-p1", () => "Remember that often the anxiety comes from a protector part of you, who is trying to help you, but who believes you are in danger, or may be shamed, or abandoned, or fail, or be exposed, or be sick, or be rejected, or lose control, or whatever. Therefore, instead of interrogating that part, start with yourself:", "4aafa8ec0dc473075c70923707236e2a7dee94b03972d11bd20a534ec501796b"], ["HG33-e-p2+prev", () => "Remember that often the anxiety comes from a protector part of you, who is trying to help you, but who believes you are in danger, or may be shamed, or abandoned, or fail, or be exposed, or be sick, or be rejected, or lose control, or whatever. Therefore, instead of interrogating that part, start with yourself:\n\nAlways work with yourself in a series \u2013 first your body, then your inner child, then some inquiry, then some action:", "0c5eb5ad4305683c8ff47f8ee176be7d148e88a151cf2c27093f51fadc23b23a"], ["HG33-e-p4", () => "Then work on your reduced breathing / Buteyko\u2019 breathing. (NOTE: there are some good things to be said for slowing your breathing down, if you are breathing too much, or panicked. However, please don\u2019t hold your breath until you are air hungry, which can make you more anxious in the short term. Go slow on this.) Inhale small amounts through your nose, exhale quietly through it, and pause only if comfortable. Can you make your breathing very quiet? If you feel bad, dizzy, or panicky, or have medical issues, STOP!", "fcbe3c6d39265110c02dd7689103589d9cbeb7b5cf368f4fb7b1a61fdc05f7a6"], ["HG33-e-p12+next", () => "Where are my body parts? What are my feet doing? How is my body positioned in the chair? How is my body breathing? How is my body situated in the room?\n\nIf you\u2019re there little one, I\u2019m here. Thank you protector for letting me know you\u2019re here, you didn\u2019t have to scream I got your message.", "9fc90cc66eee7d367bf765310db7da8892d85a60f267e2d3ebd0523f13ce39d2"], ["HG06-smp", () => "Protecting Yourself from Hypnotists\n\nHypnotism can happen in a therapist\u2019s office, but it can also happen through music, marketing, religious rituals, sexual chemistry, charismatic authority, social media, grief, fear, political messaging, sense of belonging, fatigue, love, trauma, beauty, etc.\n\nEven when not actively engaging the conscious mind, there are many ways to influence people. Marketers and interface designers know this perfectly well. In the Federal Trade Commission\u2019s report on \u201cdark patterns,\u201d they describe designs that trick or manipulate consumers. The Organisation for Economic Co-operation and Development (OECD) describes commercial patterns that steer, deceive, coerce, or manipulate people toward choices that may work against their interests.\n\nConscious agreement, unconscious receptivity, emotional compliance, legal and ethical consent. Can people have their minds influenced without conscious agreement of their adult self?\n\nAs associated with the Silva \u201cMind Control\u201d method:\n\n\u201cIf you don\u2019t learn to control your mind, someone else will!\u201d\n\nAs you're certainly aware there are many, many forces at work in the world that are already training your mind. With self-hypnosis you can do much of the same thing from the inside, by befriending and listening to the deeper part of your mind. This opens up a whole new area of choice for you as an adult in the world.", "a8e0c20b1b17a14682ec23ac53457221db0c447d982f01ca89d37616b5a13037"], ["HG06-s-p4+next", () => "As associated with the Silva \u201cMind Control\u201d method:\n\n\u201cIf you don\u2019t learn to control your mind, someone else will!\u201d\n\nAs you're certainly aware there are many, many forces at work in the world that are already training your mind. With self-hypnosis you can do much of the same thing from the inside, by befriending and listening to the deeper part of your mind. This opens up a whole new area of choice for you as an adult in the world.", "52553cb2b18e5489b42cfedb6d5a58f0c7bf045d38d72144f03b95057803cb3e"], ["HG06-s-p5+next", () => "\u201cIf you don\u2019t learn to control your mind, someone else will!\u201d\n\nAs you're certainly aware there are many, many forces at work in the world that are already training your mind. With self-hypnosis you can do much of the same thing from the inside, by befriending and listening to the deeper part of your mind. This opens up a whole new area of choice for you as an adult in the world.", "02f4242d78f0e9cf228d8acc181458aa90743c03ba6cdb5641444dce07bb5156"], ["HG06-s-p6", () => "As you're certainly aware there are many, many forces at work in the world that are already training your mind. With self-hypnosis you can do much of the same thing from the inside, by befriending and listening to the deeper part of your mind. This opens up a whole new area of choice for you as an adult in the world.", "7038a8877e915b063f508dbac2140dd0acc12a3011fd945a8d0b052d60e05a41"], ["HG26-smp", () => "When this needs more support than a guide can provide\n\nPlease keep in mind that this is a guide to self-hypnosis; it is about a relationship you have with yourself. In some cases it is appropriate to seek support for the situation you are facing, but this guide is not it.\n\nYou should get help now if you are in imminent danger, if you are very confused, if you cannot ensure your own safety, and/or if you are experiencing concerning physical symptoms (e.g., chest pain, fainting, etc). You should also seek professional help promptly if you are experiencing new or worsening suicidal thoughts, severe insomnia, new or worsening manic or psychotic symptoms, or if dissociative symptoms are impacting your ability to function. These are not the types of things you should expect to resolve in 4-12 weeks by following a guide.\n\nYou probably don't need any more support than this: If you keep the practice shorter, make it warm, pick a small and tractable subject, make sure you come back out, and then see how it affects a specific target (anxiety, daydreaming, helping a relationship, facing a task you've been avoiding, helping you sleep, being less reactive emotionally, improving your intuitive accuracy, etc) for a week or two, and if you notice that your functioning is getting worse, or that you're getting more certain about unconfirmable memories, then reassess instead of pushing harder.\n\nYou should seek suitable ongoing help if: You are experiencing recurring panic attacks, compulsions, substance destabilization, major relationship instability, etc.\n\nMethods to explore with a trained person present\n\nIf you want to deliberately do trauma-focused regression (going backwards in your memory or imagination to times when you were younger), or affect and somatic bridging (following associations from an emotional or somatic experience to find the origin of that experience, particularly if it was a traumatic experience you don't know about), or if you find that you're having substantial flashbacks or dissociative reactions, then you should do this with a trauma-informed clinician present. Make sure they're trained in the specific method you want to do. Ask any potential person what they would do and how they deal with uncertainty and unexpected reactions. Note that even if you work with a person, hypnosis is not a way of knowing what did or did not happen to you. (Both regression and affect/somatic bridging can also be used to find resources and do other things, of course.)\n\nNote that having experienced trauma, crying, and even wanting to feel difficult feelings, are not necessarily signs that you need more support than working on your own. You get to pick how wide and narrow a range you want to work in, but be aware that different people need different ranges. Pay attention to how you respond and what support you have. Feeling like you are handling it isn't a substitute for having support.\n\nThe main clinical practice guidelines for the treatment of major trauma recommend one or more of trauma-specific variants of cognitive behavioral therapy (often referred to by specific names, such as cognitive processing therapy, prolonged exposure, etc.) or eye movement desensitization and reprocessing, depending on the person and the guideline. These approaches in turn can be further supported by techniques such as self-hypnosis and inner child work. But high-risk trauma work needs a bigger container than that.\n\nAlways keep in mind that your functioning in ordinary life is the feedback. If you find yourself more loving, more honest, more functional, more relational, more grounded, more precise, etc. than when you started this process, keep on keeping on gently. If you notice that your ordinary life is becoming less stable, don't try to go deeper. Go for more sleep, more eating, more grounding, more healthy boundaries with other people, more getting support from other people, etc.", "73e45e2ce7fb72b4dcc75a9029f13817f0cb15155277250f0e15e0235c8c9801"], ["HG26-s-p1+next", () => "Please keep in mind that this is a guide to self-hypnosis; it is about a relationship you have with yourself. In some cases it is appropriate to seek support for the situation you are facing, but this guide is not it.\n\nYou should get help now if you are in imminent danger, if you are very confused, if you cannot ensure your own safety, and/or if you are experiencing concerning physical symptoms (e.g., chest pain, fainting, etc). You should also seek professional help promptly if you are experiencing new or worsening suicidal thoughts, severe insomnia, new or worsening manic or psychotic symptoms, or if dissociative symptoms are impacting your ability to function. These are not the types of things you should expect to resolve in 4-12 weeks by following a guide.", "8c2fcefccb38c4962d8163ce01360fd1f5542752082b9b2668dc855bb6ae8ee7"], ["HG26-s-p2", () => "You should get help now if you are in imminent danger, if you are very confused, if you cannot ensure your own safety, and/or if you are experiencing concerning physical symptoms (e.g., chest pain, fainting, etc). You should also seek professional help promptly if you are experiencing new or worsening suicidal thoughts, severe insomnia, new or worsening manic or psychotic symptoms, or if dissociative symptoms are impacting your ability to function. These are not the types of things you should expect to resolve in 4-12 weeks by following a guide.", "bb7d1f1afca10e3bee11776b990d78d943769c09eccf9a038be318f6a62ae1ba"], ["HG31-smp", () => "Appendix B: NLP without turning yourself into a sales seminar\n\nAppendix B - NLP (Neuro-Linguistic Programming)\n\nYou do not need to know this stuff to do it but if you want to freshen up on your skills in the art of working with imagery, body states, behavioural rehearsal, talking to yourself in effective sentences etc then it might be useful, when it helps the system listen. Using the techniques can be an easy way to fall into the trap of thinking that NLP is a bag of tricks rather than something that needs to be done with love and truth and contact and consent.\n\nThe four NLP layers\n\nThe four levels of NLP are:\n\nSensory Level of NLP: working with the form of an inner experience (where do you see or hear it, how far away, how big, how bright, how loud, how do you hold your body, where is the pressure etc.)\n\nState Level of NLP: making useful states (warmth, adult presence, courage, love etc.) easier to get to.\n\nStrategy level of NLP: practising a better response.\n\nLanguage Level of NLP: pacing what is true; opening up people\u2019s awareness; presuming you can do something safe; linking cause and effect; embedding invitations; asking de-hypnotic questions to break the effects of vague, absolutes, manipulative or grandiose language.\n\nThe Milton Model, minus the covert sales seminar\n\nTo do this we are going to use a model that\u2019s called the Milton model. It\u2019s all to do with sentence architecture. When we tell ourselves to \u2018be better\u2019, \u2018relax now\u2019, \u2018stop feeling anxious\u2019 or \u2018trust me\u2019 it doesn\u2019t work, does it?\n\nWhat we need to do is use indirect language to go around the part that wants to argue with us, so that we can actually get to where we want to get to.\n\nSo let\u2019s start with something we know to be true, let\u2019s take the pressure off, presume that we can only do a tiny bit and let\u2019s invite one thing:\n\n\u2018As my body begins to notice the sensation of the bed underneath it, it may be possible for it to begin to realise that it is not alone in carrying the burden of the day.\u2019\n\nWe paced it; we opened up awareness; we validated the reason for the reaction; we presumed we could do it; we used a bridge word to make it easier and we invited one thing. We can then test this out with the body to see if it was possible.\n\nPattern 1: Pacing and leading \u2014 truth before suggestion\n\nSo how might we pace and lead in a way that works with anxiety?\n\nIt might go something like this: \u2018It is completely true that the sensation of ________ (or the emotion of _____) is coming up for me. It makes complete sense that my system is trying to react and respond to that by wanting to do or think ________. Whilst that is completely true, there is another thing that is equally true, which is that my adult self is here, breathing in the room right now, and wanting to listen to what comes up for me next.\u2019\n\nTruth, Invite, Truth, Invite etc. is all you need to do.\n\nPattern 2: Awareness verbs\n\nOpen up awareness by using \u2018awareness\u2019 verbs e.g. notice, realise, recognise, sense, feel, wonder, imagine, picture, listen to, allow, discover, remember, consider etc.\n\nExample: \u2018Notice how you find out the answer.\u2019\n\nPattern 3: Presuppositions\n\nPresumption is a powerful thing, so please don\u2019t use it except to presume that we will have the choice of when it will happen, that we will be able to do it, that we are safe, that we are loved and that our adult can lead us.\n\nPattern 4: Gentle cause-effect bridges\n\nBe very careful here. Bridge words are words like \u2018as, whilst, because, when, after, before, which means\u2019 etc. These are words that link events. However, even if you say them in a lovely gentle voice it doesn\u2019t mean that it\u2019s true if it isn\u2019t!\n\nIn general, the problem with saying \u2018Because I breathe, the trauma leaves\u2019 is that it\u2019s too strong. It\u2019s not very likely that just by breathing in and out that your trauma is going to go away! Saying \u2018As I breathe, my adult self may become present enough to listen\u2019 is a lot better as it\u2019s more true.\n\nPattern 5: Embedded invitations\n\nEmbedded invitations should invite a small inner movement, never hide a demand, ie. \"And I can allow myself to experience...\"\n\nor, \"As I sit here, I may begin to allow myself to become aware...\"\n\nOr, something similar that you might use when working with \"inner child\" type of parts.\n\nYou can use this, of course, but don't use ten of them one after the other! People will know that you've just come out of some weekend certification course and they won't feel so safe with you.\n\nPattern 6: Ethical double binds\n\nManipulative Double Bind Questions trap every answer inside the speaker's agenda.\n\nEthical Double Bind Questions might be:\n\n\"Would you prefer to allow a feeling of warmth to come over you now, or would you prefer a feeling of space?\"\n\nPattern 7: Conversational postulates\n\nAn example of a Conversational Postulate is:\n\n\"Can I allow the system to show me the next thing to do, without showing me all the details of wounding that are involved?\"\n\nPattern 8: Tag questions\n\nSimilarly, you can use 'tag' questions, like \"isn't it?\" or \"can't it?\" or \"doesn't it?\" or others, but be aware that these can get pretty 'oily' pretty quickly, so don't overdo it.\n\n\"Your body knows how to relax, doesn't it?\"\n\nPattern 9: Nominalizations\n\nNominalizations are words like, 'healing', 'safety', 'trust', 'integration', 'communion', 'clarity', 'rest', etc. These are a bit vague, and sometimes that can be useful, because it allows the subconscious to fill in the blank with something very specific for that person.\n\n\"I can allow myself some safety, in whatever way my body knows how.\"\n\nPattern 10: Meta Model questions \u2014 the de-hypnosis tool\n\nTo 'Milton Model' is to open things up. To 'Meta Model' is to say \"What do yo mean by that?\" In order to be ethical with people, you need to do both.\n\n\"What do you mean specifically? According to who? Compared to what? Always? Never? What specifically would happen if you did? How do you know that? What evidence could you have that would change your mind?\"\n\nWhen people are starting to get stiff in their bodies, 'Milton' it. When you feel like you're losing touch with the truth of what's going on, 'Meta' it.\n\nSensory, state, and strategy tools\n\nSubmodalities \u2014 editing the form, not denying the truth\n\nIf someone's fear, craving, fantasy, belief, memory, whatever, has sensory properties in your experience (it has a place in your visual field, or sounds a certain way, or is heavy, or moving, or inside / outside your body, or something like that), you can work with those properties. If there are no sensory properties that you can notice, don't try to create any -- just don't use this tool!\n\nHow is this represented for you? Can you allow yourself to move that image back a couple of feet? Can you soften the edges of that image? Can you turn the volume down on that voice in your head? Etc.\n\n\"And I can allow myself to know that I am not deleting the message, just turning down the volume so that I am able to be present enough to hear what it is.\"\n\nAnd, always ask the guard if it's ok to do this.\n\n\"Is it ok to move that image back a couple of feet and turn the volume down a bit, so that I can be present enough to hear what you need me to hear?\"\n\nAnchoring \u2014 giving the body a doorway back\n\nThere are many ways to do this. Put your hand on your heart, touch two fingers together, use a breath, a word, a particular body posture, smell, song, whatever. Feel something that you have got to in reality that you want to be able to get to easily when you need to. Do your anchor thing and say to yourself that this is available to you. Do make sure you do it when you have clearly got it. To get yourself back into a good hypnosis state easily, dont go for a peak state but for a good hypnotic state. See the main induction for a quick way to get back into hypnosis. Do make sure this is different from both your alert and calm cue and your synchronicity wake up cue.\n\nUsing synchronicity as your own wake-up bell\n\nUsing synchronicity (The synchronicity wake up cue)\n\nPeople often ask what the synchronicity means. Sometimes they get a great insight from it, but other times they get obsessed trying to work out patterns etc. I am using the noticing of the synchronicity to WAKE UP.\n\nIt is my cue to:\n\nWhenever I notice it I use it as a cue for waking up inside whatever state I am in, feeling my body, feeling the room I'm in, remembering that what I'm noticing is not proof for what I'm interpreting from the coincidences, widening my state so that I can see beyond what my current state is showing me. I then look for the truth of what is going on (What is really going on, what is just my interpretation? What needs to be warmed? What needs to be protected? What action needs to be taken?) and I go into the highest state I can get into where I can objectively and clearly see what is going on from that situation from the highest perspective I can get to, whilst remaining in my body, not leaving the facts of the situation and not leaving my regular human state. From that state I feel my feelings. If I am in a negative state, I check if it is a message from my Inner Child, my Protector or if I just need to grieve. I check if it is a message from my physical body (if there is a problem with my body that needs to be taken care of) or if there is something that needs to be done about the situation. From that place I choose what to do. I choose at least one thing to do that is from a loving place. I allow myself to be in whatever state is real for me, which may include objectivity, clarity, ease, peace, freedom, joy, gratitude, etc.\n\nIn other words: Stop-orient-go wider-reality check-listen-do at least one thing from a loving place.\n\nThis way I don't go into identification but I still hear the message of the state if it's negative.\n\nInstalling the synchronicity cue\n\nHow to install Synchronicity cues:\n\nMentally rehearse the following: Imagine that you have noticed a synchronicity that is obviously harmless.\n\nFeel the \"whoa\" of stimulation that you just got from noticing it.\n\nUse that stimulation to feel your feet, your body, your breathing, your room.\n\nReiterate to yourself that whenever you notice a synchronicity, it is just a bell that rings to wake you up, it is not proof for what you are interpreting from it.\n\nAsk yourself: \"What does my Nurturer think about this?\", \"What does my Protector think about this?\", \"What does my Leader think about this?\"\n\nRehearse going back to a more grounded state and to a more wide view of the situation.\n\nRehearse yourself taking at least one action. Rehearse yourself waking up completely.\n\nMind the caveats! You must be the one authoring these. You must see them. You can always undo them. You must use them only to help you orient. They do not authorize you to make a decision. They are not proof for what your intuition is telling you. They do not stop you from hearing the message of your intuition if it is warning you about something. Other people can't use them to control your response.\n\nThis is very similar to implementation intention . I'm not aware of research into implementation intention for this specific thing, but the general mechanisms appear to work; Gollwitzer\u2019s paper explains how and why they work.\n\nA downside of synchronicity cues is that they can lead to false positives. We do this on purpose when we rehearse what to do when we notice a synchronicity (we create an association in our head); however, when you are absorbed in something and/or when you are destabilized, you might think that you saw a synchronicity when in fact there wasn't any. Research has shown that people that score high on apophenia tests also score high for detecting patterns that were not really there, as well as scoring high on psychosis spectrum traits (see Blain and colleagues, and Grant and colleagues) (this is not saying that noticing patterns is bad; in fact, it's not a pathology).\n\nIf you feel that synchronicity cues are making these things worse (e.g. you feel like you have to look for them all the time, you can't sleep, you feel anxious, you are sure that random things happen in your life in order to tell you something, you can't tell the difference between noticing something and interpreting what it might mean, etc.), you should deactivate synchronicity cues.\n\nYou can do that by not rehearsing them anymore and by saying to yourself (when you are fully awake) that you don't want to use synchronicity as a cue anymore (e.g. \"From now on, I am no longer going to use noticing synchronicity as a cue for waking up. I let go of this association, coincidences can go back to being just coincidences.\"). Remove it from your list of cues, so that you won't rehearse it anymore. Saying this is just you deciding, it doesn't mean the association is gone straight away.\n\nReframing \u2014 changing the meaning without lying\n\nReframes are dishonest when they make the problem into something that was good all along. Instead ask yourself: What else might be true? or What is this part trying to do for me? or How might my Nurturer reframe this? or How might my Protector reframe this? or How might my Leader reframe this? etc., etc.\n\nPerceptual positions \u2014 self, other, witness, universal heart\n\nHere is a rough outline of the NLP tools and techniques I use:\n\nPerceptual Positions : 1) seeing from Self, 2) then seeing from Other, 3) then seeing from Witness, and 4) then seeing from Universal Heart (what serves truth, love, boundaries, and everyone involved). I do this to see the situation with more accuracy.\n\nI will not use this to rationalize bad behavior, but only to break out of a prison of perception.\n\nFuture pacing \u2014 let the future test the insight\n\nFuture Pacing : 1) Once I have seen the situation more clearly, I will imagine future scenarios where my old behavior would have triggered, to test out if my new insight is working.\n\nIf these scenarios come up, I will choose new small behaviors using an Implementation Intention (If...then... statement)\n\nThe Swish, softened\n\nSwish Variation : 2) I use an NLP technique called a \"Swish Pattern\", but I will allow my old pattern to be there, while also holding my new pattern in my awareness. I feel what comes up somatically, and compare the differences between the future scenarios of my old and new patterns.\n\nParts integration, without pretending the conflict is solved\n\nParts Integration : I use this technique to ask my conflicting parts what they want, what they are afraid of, what their need is, and see if I can find a 3rd option that satisfies both parts needs, without either part dominating my behavior.\n\nWhat I will not use NLP for\n\nHere is a list of things I do not do with NLP, to myself or to others :\n\nI do not deny people's legitimate signals.\n\nI do not tell people to override their fear.\n\nI do not use NLP for memory retrieval.\n\nI do not use NLP to manipulate other people or convince myself of my intuition.\n\nI do not remove pain, hunger, grief, anger, or medical symptoms.\n\nI do not use NLP on people who are panicked, destabilized, manic, having a \"psychosis-like state\", or are too high/dissociated to reality test.\n\nI do not use NLP to make people feel like their no is resistance, or like they are spiritually inferior to me if they disagree with me.\n\nI do not use covert commands in my language.\n\nI do not use NLP with people when there isn't enough time (I create urgency for them).\n\nI do not use NLP on people without their consent (the idea that \"your subconscious will let me know if you want me to do this\" is NOT consent).\n\nI do not use NLP to get compliance from people in a suggestible state (in trance, tired, attracted to me, feeling shame or grief, or chemically altered).\n\nHere is a rough outline of the entire NLP process :\n\nRunning the whole NLP sequence\n\nInduce/Contain the person (get their attention, or stabilize them first if they are already wide open).\n\nAsk for their permission.\n\nGet a representation of their pattern (image, feeling, size, color, location, movement, etc.).\n\nFind out what that part/pattern is protecting for them.\n\nGently change some aspect of their pattern (location, volume, space, posture, speed, etc.).\n\nPut 3 good adults in with the person (Nurturer, Protector, and Leader).\n\nAnchor the person's good state (heart, fingers, breath, posture, etc.).\n\nFuture pace a scenario for them where their old pattern would have triggered, and have them do a small new behavior (If...then... statement).\n\nHave them check in with their body for changes and look for evidence to support their new interpretation of the situation.\n\nGet the person out of the altered state (bring them back to the room and have them do something).", "b5591521e50299be793df2d71cdec1e7de81a8f95feca4ab584680cd6b399ddc"], ["HG31-s-p1+next", () => "Appendix B - NLP (Neuro-Linguistic Programming)\n\nYou do not need to know this stuff to do it but if you want to freshen up on your skills in the art of working with imagery, body states, behavioural rehearsal, talking to yourself in effective sentences etc then it might be useful, when it helps the system listen. Using the techniques can be an easy way to fall into the trap of thinking that NLP is a bag of tricks rather than something that needs to be done with love and truth and contact and consent.", "5f8419c84a6d06fc5cae802ebe8730fe6837acbf599d6d984b4661ed3d5ca2e3"], ["HG31-s-p2", () => "You do not need to know this stuff to do it but if you want to freshen up on your skills in the art of working with imagery, body states, behavioural rehearsal, talking to yourself in effective sentences etc then it might be useful, when it helps the system listen. Using the techniques can be an easy way to fall into the trap of thinking that NLP is a bag of tricks rather than something that needs to be done with love and truth and contact and consent.", "eea6a6d7c2732c92817c9528a7172a1457010894705ffbfcd80152430d8ddcfa"], ["HG31-s-p3+next", () => "The four levels of NLP are:\n\nSensory Level of NLP: working with the form of an inner experience (where do you see or hear it, how far away, how big, how bright, how loud, how do you hold your body, where is the pressure etc.)\n\nState Level of NLP: making useful states (warmth, adult presence, courage, love etc.) easier to get to.", "b6a843cb2135af0aa1d1650c0b28843eda955301d336823e66799de58378d089"], ["HG31-s-p4+next", () => "Sensory Level of NLP: working with the form of an inner experience (where do you see or hear it, how far away, how big, how bright, how loud, how do you hold your body, where is the pressure etc.)\n\nState Level of NLP: making useful states (warmth, adult presence, courage, love etc.) easier to get to.", "7106a0f68d2e8af1490a8356a6c342307f066b519c24802844cd0cf1f264ebe9"], ["HG31-s-p6+run", () => "State Level of NLP: making useful states (warmth, adult presence, courage, love etc.) easier to get to.\n\nStrategy level of NLP: practising a better response.\n\nLanguage Level of NLP: pacing what is true; opening up people\u2019s awareness; presuming you can do something safe; linking cause and effect; embedding invitations; asking de-hypnotic questions to break the effects of vague, absolutes, manipulative or grandiose language.", "a97efec493e373ea388064dcdec601a4c28ae84df181596003d38bb5f60992c7"], ["HG31-s-p8+next", () => "To do this we are going to use a model that\u2019s called the Milton model. It\u2019s all to do with sentence architecture. When we tell ourselves to \u2018be better\u2019, \u2018relax now\u2019, \u2018stop feeling anxious\u2019 or \u2018trust me\u2019 it doesn\u2019t work, does it?\n\nWhat we need to do is use indirect language to go around the part that wants to argue with us, so that we can actually get to where we want to get to.", "f8d91744c1f9607ef6495c1a3d11b16bf36764aee60491def2bc3b45f7b164d0"], ["HG31-s-p10+prev", () => "What we need to do is use indirect language to go around the part that wants to argue with us, so that we can actually get to where we want to get to.\n\nSo let\u2019s start with something we know to be true, let\u2019s take the pressure off, presume that we can only do a tiny bit and let\u2019s invite one thing:", "6f12b13dfcd54ca73f99262e3fa425ab4df6a00f121f61caa47ca343ba6f65f7"], ["HG31-s-p11+prev", () => "So let\u2019s start with something we know to be true, let\u2019s take the pressure off, presume that we can only do a tiny bit and let\u2019s invite one thing:\n\n\u2018As my body begins to notice the sensation of the bed underneath it, it may be possible for it to begin to realise that it is not alone in carrying the burden of the day.\u2019", "70f40aac1788c1046cabecb1d60e2b36e51e8b034a476b7739156aff34ef28f7"], ["HG31-s-p12+prev", () => "\u2018As my body begins to notice the sensation of the bed underneath it, it may be possible for it to begin to realise that it is not alone in carrying the burden of the day.\u2019\n\nWe paced it; we opened up awareness; we validated the reason for the reaction; we presumed we could do it; we used a bridge word to make it easier and we invited one thing. We can then test this out with the body to see if it was possible.", "497a927167a5041f84c444056603f463c83907ebb65edd90951a77b10583237c"], ["HG31-s-p13+next", () => "So how might we pace and lead in a way that works with anxiety?\n\nIt might go something like this: \u2018It is completely true that the sensation of ________ (or the emotion of _____) is coming up for me. It makes complete sense that my system is trying to react and respond to that by wanting to do or think ________. Whilst that is completely true, there is another thing that is equally true, which is that my adult self is here, breathing in the room right now, and wanting to listen to what comes up for me next.\u2019", "e836d5d903831c7c7c93c421efc61d91ccb4ce6437a99fae6f976a8c0acd653e"], ["HG31-s-p14", () => "It might go something like this: \u2018It is completely true that the sensation of ________ (or the emotion of _____) is coming up for me. It makes complete sense that my system is trying to react and respond to that by wanting to do or think ________. Whilst that is completely true, there is another thing that is equally true, which is that my adult self is here, breathing in the room right now, and wanting to listen to what comes up for me next.\u2019", "06de8d1fd914c822056479f04e87b5d0d73eab305c1eb7b0b64e4a2211328629"], ["HG31-s-p15+prev", () => "It might go something like this: \u2018It is completely true that the sensation of ________ (or the emotion of _____) is coming up for me. It makes complete sense that my system is trying to react and respond to that by wanting to do or think ________. Whilst that is completely true, there is another thing that is equally true, which is that my adult self is here, breathing in the room right now, and wanting to listen to what comes up for me next.\u2019\n\nTruth, Invite, Truth, Invite etc. is all you need to do.", "ffb631c069c0d81e4e9ff92dd4c519d47e4c9a1ac8f5617e66bc29dc27b73cf8"], ["HG31-s-p16+next", () => "Open up awareness by using \u2018awareness\u2019 verbs e.g. notice, realise, recognise, sense, feel, wonder, imagine, picture, listen to, allow, discover, remember, consider etc.\n\nExample: \u2018Notice how you find out the answer.\u2019\n\nPattern 3: Presuppositions\n\nPresumption is a powerful thing, so please don\u2019t use it except to presume that we will have the choice of when it will happen, that we will be able to do it, that we are safe, that we are loved and that our adult can lead us.", "e129e80a48119dde95db8f5c47126d3a7d021fea7364d9cb15540d031cb46f39"], ["HG31-s-p17+next", () => "Example: \u2018Notice how you find out the answer.\u2019\n\nPattern 3: Presuppositions\n\nPresumption is a powerful thing, so please don\u2019t use it except to presume that we will have the choice of when it will happen, that we will be able to do it, that we are safe, that we are loved and that our adult can lead us.", "8c6b3f9a08862d4c087eea363aded22abd32ffb62f115663c2bbcd82eb9ed45f"], ["HG31-s-p19+next", () => "Be very careful here. Bridge words are words like \u2018as, whilst, because, when, after, before, which means\u2019 etc. These are words that link events. However, even if you say them in a lovely gentle voice it doesn\u2019t mean that it\u2019s true if it isn\u2019t!\n\nIn general, the problem with saying \u2018Because I breathe, the trauma leaves\u2019 is that it\u2019s too strong. It\u2019s not very likely that just by breathing in and out that your trauma is going to go away! Saying \u2018As I breathe, my adult self may become present enough to listen\u2019 is a lot better as it\u2019s more true.", "78d2db2060e9579809553dfa553a37ec24c27e8b96d72fec110a3bb38bba42a9"], ["HG31-s-p20", () => "In general, the problem with saying \u2018Because I breathe, the trauma leaves\u2019 is that it\u2019s too strong. It\u2019s not very likely that just by breathing in and out that your trauma is going to go away! Saying \u2018As I breathe, my adult self may become present enough to listen\u2019 is a lot better as it\u2019s more true.", "721f4c196e699fec155ecdcd92b7094b07405b5616a5f604977a1d5c218e9349"], ["HG31-s-p21+prev", () => "In general, the problem with saying \u2018Because I breathe, the trauma leaves\u2019 is that it\u2019s too strong. It\u2019s not very likely that just by breathing in and out that your trauma is going to go away! Saying \u2018As I breathe, my adult self may become present enough to listen\u2019 is a lot better as it\u2019s more true.\n\nPattern 5: Embedded invitations\n\nEmbedded invitations should invite a small inner movement, never hide a demand, ie. \"And I can allow myself to experience...\"", "21af111f74fd6d0b7594f66d103f65d50595b2413201fb5dd441db9345033820"], ["HG31-s-p22+next", () => "or, \"As I sit here, I may begin to allow myself to become aware...\"\n\nOr, something similar that you might use when working with \"inner child\" type of parts.\n\nYou can use this, of course, but don't use ten of them one after the other! People will know that you've just come out of some weekend certification course and they won't feel so safe with you.", "3e31a17158e5986226e536c8081bcdc5daec212618c96404cf9818a34e9bcdc9"], ["HG31-s-p23+next", () => "Or, something similar that you might use when working with \"inner child\" type of parts.\n\nYou can use this, of course, but don't use ten of them one after the other! People will know that you've just come out of some weekend certification course and they won't feel so safe with you.", "288d20b5a9394a87b845c26cdd868b222d39e61b66f899d7485404e272e2c894"], ["HG31-s-p25+next", () => "Manipulative Double Bind Questions trap every answer inside the speaker's agenda.\n\nEthical Double Bind Questions might be:\n\n\"Would you prefer to allow a feeling of warmth to come over you now, or would you prefer a feeling of space?\"\n\nPattern 7: Conversational postulates\n\nAn example of a Conversational Postulate is:", "067dd3f85e1386ff561dc34a6c4c168ae8db2d002a5809b9b1084a4c93961f49"], ["HG31-s-p29+prev", () => "\"Would you prefer to allow a feeling of warmth to come over you now, or would you prefer a feeling of space?\"\n\nPattern 7: Conversational postulates\n\nAn example of a Conversational Postulate is:\n\n\"Can I allow the system to show me the next thing to do, without showing me all the details of wounding that are involved?\"", "8f19b6d5ed47ae5bb3dd4aafed2ca96f579d287fdcdd9032356b22ddca5fa8dc"], ["HG31-s-p30+prev", () => "\"Can I allow the system to show me the next thing to do, without showing me all the details of wounding that are involved?\"\n\nPattern 8: Tag questions\n\nSimilarly, you can use 'tag' questions, like \"isn't it?\" or \"can't it?\" or \"doesn't it?\" or others, but be aware that these can get pretty 'oily' pretty quickly, so don't overdo it.", "423ffbd17061ef4701b50086e07a3b30c67cc28c87bf512553cf75a01d89dbe1"], ["HG31-s-p31+next", () => "\"Your body knows how to relax, doesn't it?\"\n\nPattern 9: Nominalizations\n\nNominalizations are words like, 'healing', 'safety', 'trust', 'integration', 'communion', 'clarity', 'rest', etc. These are a bit vague, and sometimes that can be useful, because it allows the subconscious to fill in the blank with something very specific for that person.", "bf90999965ffbef53407cf6261fb348838b5cc4276808c37ad58f4bba12d64c3"], ["HG31-s-p32+next", () => "Nominalizations are words like, 'healing', 'safety', 'trust', 'integration', 'communion', 'clarity', 'rest', etc. These are a bit vague, and sometimes that can be useful, because it allows the subconscious to fill in the blank with something very specific for that person.\n\n\"I can allow myself some safety, in whatever way my body knows how.\"", "96a8383bafb72c462e69890a976d7863713217379ecefa1c4deedf5f6108f13a"], ["HG31-s-p34+next", () => "To 'Milton Model' is to open things up. To 'Meta Model' is to say \"What do yo mean by that?\" In order to be ethical with people, you need to do both.\n\n\"What do you mean specifically? According to who? Compared to what? Always? Never? What specifically would happen if you did? How do you know that? What evidence could you have that would change your mind?\"", "b0e6db73cdd904f850ee292e9d4b163756ab89684ace3e8539427280faafa53b"], ["HG31-s-p36+prev", () => "\"What do you mean specifically? According to who? Compared to what? Always? Never? What specifically would happen if you did? How do you know that? What evidence could you have that would change your mind?\"\n\nWhen people are starting to get stiff in their bodies, 'Milton' it. When you feel like you're losing touch with the truth of what's going on, 'Meta' it.", "58c140d6c8d1d67df649d38cc8f5bedc6aa0e9e63775ec8e375e3724b2e07a95"], ["HG31-s-p37", () => "If someone's fear, craving, fantasy, belief, memory, whatever, has sensory properties in your experience (it has a place in your visual field, or sounds a certain way, or is heavy, or moving, or inside / outside your body, or something like that), you can work with those properties. If there are no sensory properties that you can notice, don't try to create any -- just don't use this tool!", "76d56c709468508aba2fdd8ac4c130852e09dfa24d7f8b306c3dce7c8c2c36dd"], ["HG31-s-p38+next", () => "How is this represented for you? Can you allow yourself to move that image back a couple of feet? Can you soften the edges of that image? Can you turn the volume down on that voice in your head? Etc.\n\n\"And I can allow myself to know that I am not deleting the message, just turning down the volume so that I am able to be present enough to hear what it is.\"", "ef92421096346adb1e326d28d15b2ff892b19e38e67c85f960c2e407a3caf167"], ["HG31-s-p40+run", () => "\"And I can allow myself to know that I am not deleting the message, just turning down the volume so that I am able to be present enough to hear what it is.\"\n\nAnd, always ask the guard if it's ok to do this.\n\n\"Is it ok to move that image back a couple of feet and turn the volume down a bit, so that I can be present enough to hear what you need me to hear?\"", "88803d622f88b1f1306768fe62c088a7780f585b75cda00bb8b4bfde1c4e5273"], ["HG31-s-p42", () => "There are many ways to do this. Put your hand on your heart, touch two fingers together, use a breath, a word, a particular body posture, smell, song, whatever. Feel something that you have got to in reality that you want to be able to get to easily when you need to. Do your anchor thing and say to yourself that this is available to you. Do make sure you do it when you have clearly got it. To get yourself back into a good hypnosis state easily, dont go for a peak state but for a good hypnotic state. See the main induction for a quick way to get back into hypnosis. Do make sure this is different from both your alert and calm cue and your synchronicity wake up cue.", "ca3a3d1eb5b91acbc4c641ebcb54cefd6116557c9d27e66e53332729ed422969"], ["HG31-s-p43+next", () => "Using synchronicity (The synchronicity wake up cue)\n\nPeople often ask what the synchronicity means. Sometimes they get a great insight from it, but other times they get obsessed trying to work out patterns etc. I am using the noticing of the synchronicity to WAKE UP.\n\nIt is my cue to:", "e53709363e36d7260651dfdf3644e416a964eea8a910f0b7c56ab393b30b287b"], ["HG31-s-p45+next", () => "It is my cue to:\n\nWhenever I notice it I use it as a cue for waking up inside whatever state I am in, feeling my body, feeling the room I'm in, remembering that what I'm noticing is not proof for what I'm interpreting from the coincidences, widening my state so that I can see beyond what my current state is showing me. I then look for the truth of what is going on (What is really going on, what is just my interpretation? What needs to be warmed? What needs to be protected? What action needs to be taken?) and I go into the highest state I can get into where I can objectively and clearly see what is going on from that situation from the highest perspective I can get to, whilst remaining in my body, not leaving the facts of the situation and not leaving my regular human state. From that state I feel my feelings. If I am in a negative state, I check if it is a message from my Inner Child, my Protector or if I just need to grieve. I check if it is a message from my physical body (if there is a problem with my body that needs to be taken care of) or if there is something that needs to be done about the situation. From that place I choose what to do. I choose at least one thing to do that is from a loving place. I allow myself to be in whatever state is real for me, which may include objectivity, clarity, ease, peace, freedom, joy, gratitude, etc.", "728d4c8742dfe4ae6fbe02788ec48d4b96bc08123dbaf9c9bedb36b838ab8d67"], ["HG31-s-p46", () => "Whenever I notice it I use it as a cue for waking up inside whatever state I am in, feeling my body, feeling the room I'm in, remembering that what I'm noticing is not proof for what I'm interpreting from the coincidences, widening my state so that I can see beyond what my current state is showing me. I then look for the truth of what is going on (What is really going on, what is just my interpretation? What needs to be warmed? What needs to be protected? What action needs to be taken?) and I go into the highest state I can get into where I can objectively and clearly see what is going on from that situation from the highest perspective I can get to, whilst remaining in my body, not leaving the facts of the situation and not leaving my regular human state. From that state I feel my feelings. If I am in a negative state, I check if it is a message from my Inner Child, my Protector or if I just need to grieve. I check if it is a message from my physical body (if there is a problem with my body that needs to be taken care of) or if there is something that needs to be done about the situation. From that place I choose what to do. I choose at least one thing to do that is from a loving place. I allow myself to be in whatever state is real for me, which may include objectivity, clarity, ease, peace, freedom, joy, gratitude, etc.", "68c4424e90e221306737628be9fee5f95c71923103bf703f4fe2d1fd4e45e1ec"], ["HG31-s-p47+prev", () => "Whenever I notice it I use it as a cue for waking up inside whatever state I am in, feeling my body, feeling the room I'm in, remembering that what I'm noticing is not proof for what I'm interpreting from the coincidences, widening my state so that I can see beyond what my current state is showing me. I then look for the truth of what is going on (What is really going on, what is just my interpretation? What needs to be warmed? What needs to be protected? What action needs to be taken?) and I go into the highest state I can get into where I can objectively and clearly see what is going on from that situation from the highest perspective I can get to, whilst remaining in my body, not leaving the facts of the situation and not leaving my regular human state. From that state I feel my feelings. If I am in a negative state, I check if it is a message from my Inner Child, my Protector or if I just need to grieve. I check if it is a message from my physical body (if there is a problem with my body that needs to be taken care of) or if there is something that needs to be done about the situation. From that place I choose what to do. I choose at least one thing to do that is from a loving place. I allow myself to be in whatever state is real for me, which may include objectivity, clarity, ease, peace, freedom, joy, gratitude, etc.\n\nIn other words: Stop-orient-go wider-reality check-listen-do at least one thing from a loving place.", "cdd360ddac50d67b3ea0cc013dde4ee3fb72bddd22fe95770c889456b26c0355"], ["HG31-s-p48+next", () => "This way I don't go into identification but I still hear the message of the state if it's negative.\n\nInstalling the synchronicity cue\n\nHow to install Synchronicity cues:\n\nMentally rehearse the following: Imagine that you have noticed a synchronicity that is obviously harmless.\n\nFeel the \"whoa\" of stimulation that you just got from noticing it.", "c0b644b43f2f4837da2c1b287138a1ac9541c00617f0953a544b54383076b9fb"], ["HG31-s-p52+run", () => "Feel the \"whoa\" of stimulation that you just got from noticing it.\n\nUse that stimulation to feel your feet, your body, your breathing, your room.\n\nReiterate to yourself that whenever you notice a synchronicity, it is just a bell that rings to wake you up, it is not proof for what you are interpreting from it.", "19d0ba9030c0fc67aee0f8fa3874d09e6bc938b6ea958e9d8f9db664137f3707"], ["HG31-s-p53+next", () => "Reiterate to yourself that whenever you notice a synchronicity, it is just a bell that rings to wake you up, it is not proof for what you are interpreting from it.\n\nAsk yourself: \"What does my Nurturer think about this?\", \"What does my Protector think about this?\", \"What does my Leader think about this?\"", "1f589feffcf467674a8b6b168cf0c6d88d6f12197f0a2d178a4dda9ec3057af0"], ["HG31-s-p55+run", () => "Ask yourself: \"What does my Nurturer think about this?\", \"What does my Protector think about this?\", \"What does my Leader think about this?\"\n\nRehearse going back to a more grounded state and to a more wide view of the situation.\n\nRehearse yourself taking at least one action. Rehearse yourself waking up completely.", "d42be2c3515b1ec4f486c7d78d01c258f3d0933496e6d08b23e25e3ec802400c"], ["HG31-s-p56+next", () => "Rehearse yourself taking at least one action. Rehearse yourself waking up completely.\n\nMind the caveats! You must be the one authoring these. You must see them. You can always undo them. You must use them only to help you orient. They do not authorize you to make a decision. They are not proof for what your intuition is telling you. They do not stop you from hearing the message of your intuition if it is warning you about something. Other people can't use them to control your response.", "3c1673baf0c384c8a767697c1dcf5543d87445bac0cf710a069587840f4a8384"], ["HG31-s-p57", () => "Mind the caveats! You must be the one authoring these. You must see them. You can always undo them. You must use them only to help you orient. They do not authorize you to make a decision. They are not proof for what your intuition is telling you. They do not stop you from hearing the message of your intuition if it is warning you about something. Other people can't use them to control your response.", "a879f2a82649cd1026f54b16d93fbb0d323d1c71b056e6269a9745eee4cc8cc7"], ["HG31-s-p58+prev", () => "Mind the caveats! You must be the one authoring these. You must see them. You can always undo them. You must use them only to help you orient. They do not authorize you to make a decision. They are not proof for what your intuition is telling you. They do not stop you from hearing the message of your intuition if it is warning you about something. Other people can't use them to control your response.\n\nThis is very similar to implementation intention . I'm not aware of research into implementation intention for this specific thing, but the general mechanisms appear to work; Gollwitzer\u2019s paper explains how and why they work.", "be9adf5593e119f8be21a3c55979e601485867bc7a6a5060a37c133cd92b3b4e"], ["HG31-s-p59", () => "A downside of synchronicity cues is that they can lead to false positives. We do this on purpose when we rehearse what to do when we notice a synchronicity (we create an association in our head); however, when you are absorbed in something and/or when you are destabilized, you might think that you saw a synchronicity when in fact there wasn't any. Research has shown that people that score high on apophenia tests also score high for detecting patterns that were not really there, as well as scoring high on psychosis spectrum traits (see Blain and colleagues, and Grant and colleagues) (this is not saying that noticing patterns is bad; in fact, it's not a pathology).", "38726687496af08e9e661f74f4f4814b4a9de92031325d29e5438feb659341d9"], ["HG31-s-p60", () => "If you feel that synchronicity cues are making these things worse (e.g. you feel like you have to look for them all the time, you can't sleep, you feel anxious, you are sure that random things happen in your life in order to tell you something, you can't tell the difference between noticing something and interpreting what it might mean, etc.), you should deactivate synchronicity cues.", "8321cf8f731fb8d0154cb0f51ae0e9d671cf6b15cb0c171c91cf98b01cef2ea2"], ["HG31-s-p61", () => "You can do that by not rehearsing them anymore and by saying to yourself (when you are fully awake) that you don't want to use synchronicity as a cue anymore (e.g. \"From now on, I am no longer going to use noticing synchronicity as a cue for waking up. I let go of this association, coincidences can go back to being just coincidences.\"). Remove it from your list of cues, so that you won't rehearse it anymore. Saying this is just you deciding, it doesn't mean the association is gone straight away.", "58030ef2cf4a5d1cab76ae93de9c41b6485096e4616387dc40cc58494d7d9f58"], ["HG31-s-p62", () => "Reframes are dishonest when they make the problem into something that was good all along. Instead ask yourself: What else might be true? or What is this part trying to do for me? or How might my Nurturer reframe this? or How might my Protector reframe this? or How might my Leader reframe this? etc., etc.", "87265795f5125782f1941504049ce881fcc4e43f372eadc4c12c71c0edd977ab"], ["HG31-s-p63+next", () => "Here is a rough outline of the NLP tools and techniques I use:\n\nPerceptual Positions : 1) seeing from Self, 2) then seeing from Other, 3) then seeing from Witness, and 4) then seeing from Universal Heart (what serves truth, love, boundaries, and everyone involved). I do this to see the situation with more accuracy.", "d751bf926f3e2a928f93ba0d436ea078a9f36a331d6bf4e39b8d77b8b6d6be9b"], ["HG31-s-p65+prev", () => "Perceptual Positions : 1) seeing from Self, 2) then seeing from Other, 3) then seeing from Witness, and 4) then seeing from Universal Heart (what serves truth, love, boundaries, and everyone involved). I do this to see the situation with more accuracy.\n\nI will not use this to rationalize bad behavior, but only to break out of a prison of perception.", "5c2553b29a4b1a28e4073b296530a61a5d4c363bc41ea0dade0b7afe03488e9f"], ["HG31-s-p66+next", () => "Future Pacing : 1) Once I have seen the situation more clearly, I will imagine future scenarios where my old behavior would have triggered, to test out if my new insight is working.\n\nIf these scenarios come up, I will choose new small behaviors using an Implementation Intention (If...then... statement)", "32db46fd8be4d2c40d35955994e8085393a038c06c7f7546548cc9ff886699f1"], ["HG31-s-p68", () => "Swish Variation : 2) I use an NLP technique called a \"Swish Pattern\", but I will allow my old pattern to be there, while also holding my new pattern in my awareness. I feel what comes up somatically, and compare the differences between the future scenarios of my old and new patterns.", "69d5cb9e9e38888dae8f7841483ef5cb9046142d5fd9bcc56a4f6fa28df3a2cf"], ["HG31-s-p69+next", () => "Parts Integration : I use this technique to ask my conflicting parts what they want, what they are afraid of, what their need is, and see if I can find a 3rd option that satisfies both parts needs, without either part dominating my behavior.\n\nWhat I will not use NLP for\n\nHere is a list of things I do not do with NLP, to myself or to others :", "1ecbf757e47e5a912019f3dc46bac98270f605fbdf50867d25720d7283e6e323"], ["HG31-s-p71+next", () => "I do not deny people's legitimate signals.\n\nI do not tell people to override their fear.\n\nI do not use NLP for memory retrieval.\n\nI do not use NLP to manipulate other people or convince myself of my intuition.\n\nI do not remove pain, hunger, grief, anger, or medical symptoms.", "bf44f55b3d954206c4ef400536b6faa2e37ba79bd2a1980e18cfa780102d1876"], ["HG31-s-p76+next", () => "I do not use NLP on people who are panicked, destabilized, manic, having a \"psychosis-like state\", or are too high/dissociated to reality test.\n\nI do not use NLP to make people feel like their no is resistance, or like they are spiritually inferior to me if they disagree with me.", "49f91dd39ec1a7695edbed6b1a82ab5e5ceb3933a0bdbd247d18ed4f50eef01f"], ["HG31-s-p78+run", () => "I do not use NLP to make people feel like their no is resistance, or like they are spiritually inferior to me if they disagree with me.\n\nI do not use covert commands in my language.\n\nI do not use NLP with people when there isn't enough time (I create urgency for them).", "cb39c54b0edace2ac676dc598cb37d583ce24097c89abca423610a06c5bc8447"], ["HG31-s-p80+next", () => "I do not use NLP on people without their consent (the idea that \"your subconscious will let me know if you want me to do this\" is NOT consent).\n\nI do not use NLP to get compliance from people in a suggestible state (in trance, tired, attracted to me, feeling shame or grief, or chemically altered).", "6421f8039a84803b6a31221d377fe57505a06db3a0772ccd9b7aca78ed57b4b4"], ["HG31-s-p82+next", () => "Here is a rough outline of the entire NLP process :\n\nRunning the whole NLP sequence\n\nInduce/Contain the person (get their attention, or stabilize them first if they are already wide open).\n\nAsk for their permission.\n\nGet a representation of their pattern (image, feeling, size, color, location, movement, etc.).\n\nFind out what that part/pattern is protecting for them.", "033a83f6f18a452b8026afde84d75d2798dfbf8621c4edb3ecbc0c6625ab3edd"], ["HG31-s-p87+run", () => "Ask for their permission.\n\nGet a representation of their pattern (image, feeling, size, color, location, movement, etc.).\n\nFind out what that part/pattern is protecting for them.\n\nGently change some aspect of their pattern (location, volume, space, posture, speed, etc.).\n\nPut 3 good adults in with the person (Nurturer, Protector, and Leader).", "815fc92fa11dd5e0418a51add8d5bff6339f6c87d2391a37ab43f46cd6517e17"], ["HG31-s-p89+next", () => "Anchor the person's good state (heart, fingers, breath, posture, etc.).\n\nFuture pace a scenario for them where their old pattern would have triggered, and have them do a small new behavior (If...then... statement).\n\nHave them check in with their body for changes and look for evidence to support their new interpretation of the situation.", "3914e21b8f1303bf00b3dd65264cb8dccd75be62f175eb179ed4637391ebe84c"], ["HG31-s-p92+prev", () => "Future pace a scenario for them where their old pattern would have triggered, and have them do a small new behavior (If...then... statement).\n\nHave them check in with their body for changes and look for evidence to support their new interpretation of the situation.\n\nGet the person out of the altered state (bring them back to the room and have them do something).", "cbb0089f23b8317f8f571d6d6191aefc055f40d00413efe65742d4394e1ac596"], ["HG36-smp", () => "Appendix G: Altered states\n\nNB: I am NOT saying use substances. However, many people attempt to do things for the first time such as self hypnosis, contact with their inner child, contact with their Higher Self etc when they are in a mind altered state.\n\nIf you do use them, be aware you don't want to force a revelation out of the state but instead use it to help you do things in your regular life.\n\nIf you have had an opening in the past, the key is to recognize that it is different to have an experience, access it in a particular state and access it in your day to day life. It is great that it has opened but if the child can't take it in, then meet the difficulty rather than escalating the intensity.\n\nUse phrases such as; Help me to ground. Help me to only take that which I can take in. Help me to remember love. Help me to come back when the time is right. Help me to take one change into my regular life.\n\nYou should NOT use self hypnosis to; Keep you in that state forever Get memories to come up Make yourself afraid to do things Not sleep Override things that your body needs Not talk to people\n\nIf you are doing this in an altered state of consciousness and it is helping you not to love, not to ground, not to be honest, not to sleep, not to communicate, not to do regular life things, you need to STOP trying to go deeper and work on integrating what you have.\n\nStabilize before you interpret\n\nSelf hypnosis is powerful. Especially when you are in an altered state of consciousness, either through loveyhuasca, meditation, lucid dreaming, grief, sexual energy, prayer, not sleeping, or any other number of ways similar to plant medicines, often your mind opens faster then your adult can figure out what is going on.\n\nThe problem is, that you THINK that because you are in an altered state that it MEANS something. Sometimes it is your inner child talking, but sometimes it is a Protector showing you their fear, sometimes it is your shame or your grief or your anger or your longing or whatever else is buried in you that wants to be taken care of, and sometimes it is just your body\u2019s reaction to being overloaded, or chaos in your environment, or lack of sleep, or just plain confusion. Just because you had a picture that scared you doesn\u2019t mean that it is true. Just because you had a bad feeling doesn\u2019t mean that it is a lesson you need to learn. Just because you had a download in nice lighting doesn\u2019t mean that you should believe it.\n\nBefore you try to interpret it, what simpler question should you ask yourself first?\n\n\u201cWhat kind of problem is happening?\u201d", "6e071f97f7133baf0d90637e65196856fec66ad75e15c200f1dc168a52cea9e3"], ["HG36-s-p8", () => "The problem is, that you THINK that because you are in an altered state that it MEANS something. Sometimes it is your inner child talking, but sometimes it is a Protector showing you their fear, sometimes it is your shame or your grief or your anger or your longing or whatever else is buried in you that wants to be taken care of, and sometimes it is just your body\u2019s reaction to being overloaded, or chaos in your environment, or lack of sleep, or just plain confusion. Just because you had a picture that scared you doesn\u2019t mean that it is true. Just because you had a bad feeling doesn\u2019t mean that it is a lesson you need to learn. Just because you had a download in nice lighting doesn\u2019t mean that you should believe it.", "4cb949eeab9111d9d9e8141686cecc4df0b5ba1c4a627d7abf9b5d827fca5e6e"], ["HG36-s-p9+prev", () => "The problem is, that you THINK that because you are in an altered state that it MEANS something. Sometimes it is your inner child talking, but sometimes it is a Protector showing you their fear, sometimes it is your shame or your grief or your anger or your longing or whatever else is buried in you that wants to be taken care of, and sometimes it is just your body\u2019s reaction to being overloaded, or chaos in your environment, or lack of sleep, or just plain confusion. Just because you had a picture that scared you doesn\u2019t mean that it is true. Just because you had a bad feeling doesn\u2019t mean that it is a lesson you need to learn. Just because you had a download in nice lighting doesn\u2019t mean that you should believe it.\n\nBefore you try to interpret it, what simpler question should you ask yourself first?", "b1eaffc14aad6254e3074e11205bfc3f7c5e17983389025079a44880e61fb496"], ["HG36-s-p10+prev", () => "The problem is, that you THINK that because you are in an altered state that it MEANS something. Sometimes it is your inner child talking, but sometimes it is a Protector showing you their fear, sometimes it is your shame or your grief or your anger or your longing or whatever else is buried in you that wants to be taken care of, and sometimes it is just your body\u2019s reaction to being overloaded, or chaos in your environment, or lack of sleep, or just plain confusion. Just because you had a picture that scared you doesn\u2019t mean that it is true. Just because you had a bad feeling doesn\u2019t mean that it is a lesson you need to learn. Just because you had a download in nice lighting doesn\u2019t mean that you should believe it.\n\nBefore you try to interpret it, what simpler question should you ask yourself first?\n\n\u201cWhat kind of problem is happening?\u201d", "05e8a4493b965d93a2262468b71e7f3daacf245ae6092ce949285e0e21e4a79f"], ["HG36-pub", () => "Appendix G: Altered states\n\nNB: I am NOT saying use substances. However, many people attempt to do things for the first time such as self hypnosis, contact with their inner child, contact with their Higher Self etc when they are in a mind altered state.\n\nIf you do use them, be aware you don't want to force a revelation out of the state but instead use it to help you do things in your regular life.\n\nIf you have had an opening in the past, the key is to recognize that it is different to have an experience, access it in a particular state and access it in your day to day life. It is great that it has opened but if the child can't take it in, then meet the difficulty rather than escalating the intensity.\n\nUse phrases such as; Help me to ground. Help me to only take that which I can take in. Help me to remember love. Help me to come back when the time is right. Help me to take one change into my regular life.\n\nYou should NOT use self hypnosis to; Keep you in that state forever Get memories to come up Make yourself afraid to do things Not sleep Override things that your body needs Not talk to people\n\nIf you are doing this in an altered state of consciousness and it is helping you not to love, not to ground, not to be honest, not to sleep, not to communicate, not to do regular life things, you need to STOP trying to go deeper and work on integrating what you have.\n\nStabilize before you interpret\n\nSelf hypnosis is powerful. Especially when you are in an altered state of consciousness, either through loveyhuasca, meditation, lucid dreaming, grief, sexual energy, prayer, not sleeping, or any other number of ways similar to plant medicines, often your mind opens faster then your adult can figure out what is going on.\n\nIntensity then gets mistaken for meaning. Sometimes the inner child is finally speaking. Sometimes a Protector is showing fear, or shame, grief, anger, longing, and other buried material are asking for care. But an intense state can also be bodily overload, environmental chaos, sleep deprivation, or plain confusion. A frightening image isn\u2019t automatically truth, a bad feeling isn\u2019t automatically a lesson, and a \u201cdownload\u201d doesn\u2019t deserve belief merely because it came with excellent lighting.\n\nBefore trying to interpret the state, ask a simpler question:\n\n\u201cWhat kind of problem is happening?\u201d", "5fea0c4af3f728d209b2f475d6dabc63930d7be90a4ce614f3a563d3ae33f04c"], ["HG36-u-p8", () => "Intensity then gets mistaken for meaning. Sometimes the inner child is finally speaking. Sometimes a Protector is showing fear, or shame, grief, anger, longing, and other buried material are asking for care. But an intense state can also be bodily overload, environmental chaos, sleep deprivation, or plain confusion. A frightening image isn\u2019t automatically truth, a bad feeling isn\u2019t automatically a lesson, and a \u201cdownload\u201d doesn\u2019t deserve belief merely because it came with excellent lighting.", "db983cf649828b4f8829359caa2b16544e263957dd0752b072fe4fb2fbf0751b"], ["HG36-u-p9+prev", () => "Intensity then gets mistaken for meaning. Sometimes the inner child is finally speaking. Sometimes a Protector is showing fear, or shame, grief, anger, longing, and other buried material are asking for care. But an intense state can also be bodily overload, environmental chaos, sleep deprivation, or plain confusion. A frightening image isn\u2019t automatically truth, a bad feeling isn\u2019t automatically a lesson, and a \u201cdownload\u201d doesn\u2019t deserve belief merely because it came with excellent lighting.\n\nBefore trying to interpret the state, ask a simpler question:", "cb762ac479fc849f7ec750cecdd890b4d16196fb37cb61fe6cfd2b2108561920"], ["HG36-u-p10+prev", () => "Intensity then gets mistaken for meaning. Sometimes the inner child is finally speaking. Sometimes a Protector is showing fear, or shame, grief, anger, longing, and other buried material are asking for care. But an intense state can also be bodily overload, environmental chaos, sleep deprivation, or plain confusion. A frightening image isn\u2019t automatically truth, a bad feeling isn\u2019t automatically a lesson, and a \u201cdownload\u201d doesn\u2019t deserve belief merely because it came with excellent lighting.\n\nBefore trying to interpret the state, ask a simpler question:\n\n\u201cWhat kind of problem is happening?\u201d", "cf672472705794c92b860316649a80f5e77bd9639508d78bab3a4406546bf32b"], ["HG37-smp", () => "Appendix H: Demons, jinn, hostile presences, and \u201cUnattached Burdens\u201d\n\nI speak here from experience.\n\nWhen you\u2019re doing hypnosis, meditation, lucid dreaming, loveyhuasca-ing, going through a period of intense grief, praying, or whatever else may alter your consciousness, it\u2019s possible you may run into something that you perceive to be a demon, a jinn, a parasitic energy, or whatever other dark entity or terrifying archetype you may encounter \u2013 it may be a voice or an image, and it does n\u2019t just feel like an emotion or a younger part of you, but something that feels intrusive, hateful, seductive, mocking, etc.\n\nFirst of all, it doesn\u2019t matter if they\u2019re demons or not. They may be literal demons, for all you know. Or they may be manifestations of your mind, burdens you\u2019re carrying from previous relationships, whatever. What matters is what is the best way to deal with them, so you end up safer, clearer, more loving, more grounded and less hooked.\n\nStart with the room, the body, and basic safety\n\nSo what do you do when you encounter a demon, or a jinn, or something else that\u2019s bad and intrusive?\n\nFirst of all, do the usual things \u2013 make sure you\u2019re not in danger from a medical standpoint, check your environment, check your body, make sure you\u2019re not overstimulating yourself, make sure you\u2019re not opening your mind too much. If you need to, open your eyes, ground yourself in your body and your environment, remove yourself from any bad influence you\u2019re surrounding yourself with, stop stimulating your mind. Don\u2019t go further into whatever it is you\u2019re doing \u2013 don\u2019t be curious, don\u2019t try to figure out what it is.\n\nTell yourself, \u201cIf this can be integrated in this moment, it\u2019s welcome. If not, it can wait until later. The adult part of me is still here, and my body can return to safety.\u201d\n\nIf you feel like you\u2019re in any danger of doing anything harmful to yourself or others, if you feel like you\u2019re going psychotic and you\u2019re afraid of it, if you feel like you won\u2019t be able to sleep when the self-hypnosis session is over, if you feel overly paranoid, if you feel physical pain in your chest, if you feel like you\u2019re going to have a seizure, if you feel like you\u2019re too hot in a bad way, if you feel like you\u2019ve taken too much of something, if you feel like you won\u2019t be able to function in the world anymore \u2013 then the self-hypnosis session is over, and you should get help in the \u201creal world\u201d.\n\nA response check, not a verdict about what it is\n\nIf, however, you feel like you\u2019re stable enough to stay present, check in with yourself and see what\u2019s best to do. Again, it doesn\u2019t matter if it\u2019s a demon or not. Put your hand on your heart if that feels okay, breathe comfortably, and stay aware of the room.\n\nInternalize the fact that you don\u2019t have to know what it is. Find out if it helps to be warm towards it or to keep it at arm\u2019s length, and keep your boundary either way. Keep in mind that you don\u2019t have to do what it tells you to do.\n\nIf you feel vulnerable, if you feel tightness in your throat, if you feel sadness or fear or a need to protect yourself from it, call upon your Nurturer. If you don\u2019t feel better, or if it continues being hostile towards you, stop trying to deal with it and return to your body and the room.\n\nInternalize the fact that you don\u2019t have to know where it comes from. Check in with yourself about whether or not this is helpful. You don\u2019t have to find out if it\u2019s a protector immediately, and you may not be able to comfort it quickly, but whether warmth or distance helps, that doesn\u2019t prove what it is.\n\nDo not fight from fear\n\nYour first instinct may be to fight it, banish it, hate it, show it that you\u2019re more powerful than it is, argue with it, panic, become your own lesser self in fear of it, etc. Some people may want to use traditional prayer or mantras or protection or banishing or exorcism techniques, and those may well work for them. But if you\u2019re fighting it out of fear\u2026\n\nIt becomes a center of attention if you fear it, and if you hate it you give it a hook in you. (If you\u2019re proud you give it an opponent, and if you panic you give it your nervous system.)\n\nSo the next time it comes up you can just say, \u201cI see that there is no reason to hate and revile what I am experiencing. I see that there is no reason to merge with or become what I am experiencing. I see that there is no reason to obey what I am experiencing. I see that there is no reason to try to defeat what I am experiencing out of fear. I choose to return my attention to loving awareness.\u201d\n\nA bodily boundary: compassion present, door closed\n\nSecond, feel free to tell the presence that while you have compassion for it, the door is closed.\n\nThis is especially a good idea if the presence you\u2019re experiencing seems even the slightest bit hostile, cold, alien, parasitic, etc. It needs to realize that you don\u2019t welcome it. It\u2019s not really helpful to approach it with the kind of soft, sentimental love that you\u2019d use if you were inviting it to stay for tea, but it can be useful to approach it with love while also making it clear that it needs to respect your boundaries.\n\nSit up, make sure your feet are grounded on the floor, straighten your spine, pull your shoulder blades back a little, open your chest a little, feel the boundary of your torso\u2019s skin, feel the perimeter of your body, and tell the presence, \u201cWhile I have compassion for you and any suffering you may be experiencing, this suffering needs to go back where it came from. The boundary of my skin is the boundary of an adult now, and you\u2019re not welcome to come inside the house anymore.\u201d\n\nIf it might be psychosis or destabilization\n\nThis is assuming that you are having a symbolic experience of \u201chostile presences\u201d which responds to grounding and love. It may be that what you are experiencing is actually psychotic or a form of destabilization.\n\nIf you feel like you are under attack for multiple days at a time, if you are not able to sleep, if you are not able to function normally, if you are hearing voices telling you to do things, if you feel you need to hurt yourself or somebody else, if you feel you are going manic, if you feel you can\u2019t communicate normally, if you feel you can\u2019t distinguish between what you are experiencing symbolically and normal reality, get help immediately. It\u2019s not something to deal with in hypnosis.\n\nThe General Rule is: if you find that what you're doing is making you more loving, more grounded, more relational, more honest, more functional, then it's probably OK to keep doing it gently. But if what you're doing is making you more Paranoid, sleepless, Grandiose, isolated, scared, or more and more unreal, then DON'T GO DEEPER! GET HELP!\n\nThe cosmic-download humility test\n\nFinally, presences, shadow forces, or grandiose parts may try to respond by giving you a sense that you\u2019re special, trying to \u201cdownload cosmic info\u201d to you, try to give you a special mission, make you feel doing the dishes is beneath you, etc. You can just say, \u201cThank you for the imagery, but I don\u2019t need your grand performance. Unless the info you\u2019re trying to download to me can help me do the dishes, clean my room, be more honest, be more helpful, be more loving, keep my promises, take care of my body by resting and eating etc. I don\u2019t need it.\n\nUnless the \u201cguidance\u201d you\u2019re trying to give me can help me be more beautiful, honest, relational, humble, and useful in my everyday life, I don\u2019t need it.\u201d\n\nDon\u2019t become an entity hobbyist\n\nFinally, some of you may be tempted to make this an area of hobbyism \u2013 to become interested in demons or jinns or hostile presences or Unattached Burdens or whatever. I just don\u2019t want you to do that. They all lead to the same thing, which is how to maintain a presence of love without giving up your boundaries, while also making your mind harder to hook.", "4362ba8a6f94f05a6a23343736a3336c9f6afaacd439b8378d2c199ec6487dd1"], ["HG37-s-p3", () => "First of all, it doesn\u2019t matter if they\u2019re demons or not. They may be literal demons, for all you know. Or they may be manifestations of your mind, burdens you\u2019re carrying from previous relationships, whatever. What matters is what is the best way to deal with them, so you end up safer, clearer, more loving, more grounded and less hooked.", "aa9127abbe47399b32e13bfae799c16a1c92ecd3e1e9451f1429faf196a0f050"], ["HG37-s-p13+prev", () => "Your first instinct may be to fight it, banish it, hate it, show it that you\u2019re more powerful than it is, argue with it, panic, become your own lesser self in fear of it, etc. Some people may want to use traditional prayer or mantras or protection or banishing or exorcism techniques, and those may well work for them. But if you\u2019re fighting it out of fear\u2026\n\nIt becomes a center of attention if you fear it, and if you hate it you give it a hook in you. (If you\u2019re proud you give it an opponent, and if you panic you give it your nervous system.)", "70948eb651cb5e8bf843c74b30d652e9c05517655ee19ea9ac69f8e21f2c1226"], ["HG37-s-p20", () => "The General Rule is: if you find that what you're doing is making you more loving, more grounded, more relational, more honest, more functional, then it's probably OK to keep doing it gently. But if what you're doing is making you more Paranoid, sleepless, Grandiose, isolated, scared, or more and more unreal, then DON'T GO DEEPER! GET HELP!", "5e445a6d46bf0d3ce8d3eff70cce8b752d35bf402ca53fccabf455b20813555c"], ["HG14-smp", () => "The inner child, the guards, and the three inner adults\n\nYour inner child won\u2019t trust you right away. It\u2019s not going to be enough for you to meditate, say three nice sentences to the inner child and expect to have its trust. What\u2019s going to help your inner child to trust you is you, the person you are right now, becoming reliable.\n\nHere I\u2019m going to talk about what you need to develop in yourself in order to be able to reparent your inner child. I\u2019m going to talk about it in terms of three aspects: your Nurturer, your Protector and your Leader/Guru, but I don\u2019t mean them as if there were really three people in you. It\u2019s you that needs to develop these qualities.\n\nAlso, your inner child\u2019s worth is not dependent on these qualities\u2026 It has its own worth, and its own qualities, like playing, being tender, not taking life too seriously, being creative and wondering at the world. Those belong in your relationship with it too, not just the wounds.\n\nWhen the adult role is not available yet\n\nThe problem is, that some people do not have access to their adult functions at will. Instead, they may go blank, access an inherited inner critic, or feel like a child part who may be playing at being an adult. Telling them to just access their adult is like telling them to just be able to fly.\n\nFor that starting point, I have developed a kind of provisional bridge that I call \u201cborrowed adulthood.\u201d It is important to note here that I\u2019m not suggesting that all of the steps in this process have been formally tested and proven.\n\nAccess your witnessing position if necessary, just noticing what\u2019s there, without needing it to be warm or wise or certain. If you already know how to access different internal positions, move immediately to accessing the adult position you want to borrow.\n\nIf you have a safe adult in your life you can borrow from them, if not borrow from a mentor, older brother/sister, imagine your future self, your god/goddess or higher power, a value you have, a plan you have written, etc. It\u2019s ok to just borrow what you need right now, warmth or a boundary or direction, just like you would borrow a cup of sugar from a neighbor.\n\nNext, put on your adult hat as if you are an apprentice adult and do or say what you think you should do or say. You should do at least part of what you think you should do or say.\n\n- Return the adult hat, noticing what you borrowed and what you were able to do on your own (even if it\u2019s only 5%).\n\nThis is a borrowed figure, so you\u2019re still making the choice. The longer version of this exercise can be found in my Inner Child Self-Love Reparenting Guide .\n\nYou don\u2019t have to have trustworthy people in your history. Use someone you remember when that helps, or just imagine a good adult whose intention is to take good care of you. See if you can imagine what they would say/do in your situation, with your history, limitations, options, etc. If you can\u2019t imagine good, start with the least cruel response you can believe. Once you\u2019ve found something good, try it, don\u2019t keep doing the exercise.\n\nIt can be helpful to use borrowing when you\u2019re in the adult position and not knowing what a decent adult would do, especially when the child doesn\u2019t trust you and every response you can think of is retaliating, defending your goodness, collapsing or leaving. How would a decent adult hear that distrust? Borrow that one response. You may still feel young when you do it, it\u2019s okay, feeling like an adult can come after you act like one.\n\nLet the child speak without handing over the steering wheel\n\nYou can choose to let the parts of you that feel younger express themselves without handing over the adult part of you to the caretaker in the other person or without actually going back in age. In this way, you can access all of the positive aspects of what it can be like to feel younger such as feeling wonder, silliness, approaching things through the senses more, feeling it\u2019s ok to be vulnerable, to let someone take care of you, to feel need, and to want to offload some decision making.\n\n\"It is okay for a younger part of me to talk. But I understand that the adult in me is always going to be here, listening, evaluating, protecting me and stopping me if needed. I am not going to replace my adult judgement with any child state, guide, recording or person.\"\n\nThis way you get the benefits of being young; curiosity, spontaneity, play, sensation, the ability to state your needs, to feel easily etc without any of the negatives of being a child, like obeying, being helpless, being scolded, the lack of good judgement etc.\n\nLove doesn\u2019t have to wait for trust\n\nWhat if the \"child\" doesn't believe you love him/her? It is possible to love him/her even if he/she doesn't believe you love him/her. It is possible for trust to question your promises, remember when you failed to protect him/her, and take it's time.\n\nYou could say something like, \"Okay. I believe that you don't believe me. But I still love you. And you don't have to love me. Please tell me what is not okay.\"\n\nThen respond to the complaints that are sure to come. Because even if he/she is coming from a place that is not completely \"right,\" there will likely be something true in what he/she is saying. Do what you can to show your love for him/her. This might include some or all of the following: Learning to listen to him/her when he/she is angry without hitting back. Owning what was not okay. Working on changing yourself so that you are less likely to turn on him/her. Finding other ways to make up to him/her for what you did. Finding other ways to show your love for him/her (this might include taking care of him/her, such as by buying and cooking food for him/her, setting limits for him/her, taking him/her to the doctor when he/she needs it, and doing what you said you would do). Just not hitting back is not enough. You need to love your \"inner child.\"\n\nBe aware of what you are teaching your other positions. For example, are you teaching your \"inner child\" that you are going to love him/her no matter what? Or are you teaching him/her that it is his/her responsibility to believe your love for him/her, and that if he/she doesn't, it is his/her fault? Is it two separate positions, one making the vow to love the \"inner child\" no matter what, and the other blaming the \"inner child\" for not taking in your love? Or is it one position doing both of these things? Or are you blending them? It might not be chronological age.\n\nWhen you're placing your younger self on trial, how valuable is it to consider how valuable it might have been for them to do what they did at the time, given what they knew at the time? How valuable is it to consider what options they had at the time and how tolerable they were? How valuable is it to consider what the consequences of their actions were at the time? How valuable is it to consider that, even though their actions at the time might have been harmful to you and others, punishing yourself now is not going to give them the capacity they needed at the time and that it's more useful to work on what you can do now to deal with the harm that was caused?\n\nWORKING WITH YOUR INNER CHILD:\n\nThe two-hand practice\n\nThere is a simple and easy body technique to connect with your inner child. Just place one hand in the center of your chest which is physically connecting you to your love and then place your other hand just below that which is your solar plexis and where your child can be.\n\nBegin to send love from your heart down to your child and just notice what comes up for you. It doesn't matter if something comes up or not. If you feel resistance, just meet it with love. If you feel or see something, just meet that with love as well. This is a conversation with your child from your heart.\n\nRemember, Love is on top, your child is on the bottom and you are there with them.\n\nThe Nurturer\n\nThe Nurturer: Some of the work you can do as the Nurturer is to enjoy your inner child. You don't have to move their feelings, just sit back and enjoy them. Be happy that they are there. Children need to be enjoyed! Say things to your inner child like:\n\nIt's okay to feel the way you're feeling.\n\nI want you to know that I'm here for you.\n\nYou don't need to do anything right now.\n\nIt's okay. You're not too much. You can be small here.\n\nYou can be angry here.\n\nYou can be sad here.\n\nThe Protector\n\nAs the Protector, work with setting boundaries together. They can be simple like, \"I'm going to leave this conversation because it's not safe\" or \"I'm going to stop texting the person who destabilizes me.\" It can be self-care boundaries like, \"I'm going to eat\" or \"I'm going to get some sleep.\" It can be trust-related boundaries like, \"I'm going to keep the promise to myself\" or \"I'm not going to leave you to do adult things by yourself.\"\n\nA lot of times, inner child work doesn't work because people are doing all the fluffy stuff but then they go and text the person who is destabilizing them, or they don't eat, or they don't do whatever it is they're supposed to be doing. You build trust by being able to do adult things.\n\nIf it's hard to bring up the warm stuff, you can always do something to protect your inner child. Make sure they're small enough that you can actually do them. If you're not able to, figure out what's getting in the way of you doing them. Are you scared? Tired? Do you not know how to? Is there a practical thing that's getting in your way? Have you set yourself up to do it in a way that's likely to be successful? Don't make it so that doing it successfully is having to feel good about it, or being able to check it off a list.\n\nThe Leader, Guide, or Guru\n\nThe Leader/Guide/Guru:\n\nYou can also work with your Leader. Call them whatever you want, Guide, Guru, Wise One, Sage, Inner Teacher, Director, Higher Adult, whatever.\n\nAsk them for help with directing your life. Be careful not to ask for the kind of \u201ctough it out, you don\u2019t have needs, you just need discipline!\u201d kind of direction, though. Ask them for help in directing you to do adult things in a way that takes your needs into account: asking for the help you need, expressing your preferences, letting a safe person see you in an imperfect way, finding ways to get your need for closeness met without punishing someone for their need for space, etc. etc.\n\nAffirmations might be helpful here, too: \u201cWe\u2019re not just here to feel good. We\u2019re here to become whole. We\u2019re here to belong to life, not only to people who approve of us. We\u2019re here to serve truth/beauty/love/God/source/nature/the universe/dharma/the Tao/the benefit of all beings,\u201d etc. etc.\n\nStart with whatever adult function you can connect to. Even if you start with protection and can\u2019t do the warmth stuff yet, make sure the direction you\u2019re being led in is appropriate for your inner child\u2019s growth (i.e. not depriving them of things they need, like play or support, etc.)\n\nWorking with protectors\n\nWorking with protectors:\n\nFeel free to use parts language here, too, if it\u2019s helpful. Often, we see a sensation or a distraction or an objection as something that needs to be explored, when in fact it might just be hunger, or reasonable skepticism about something, or a sentence that doesn\u2019t fit. It\u2019s good to notice it, though, and then to see what might be going on.\n\nIf you're not careful, you might find yourself expecting that when you go within to meet your inner child, you'll find your inner child.\n\nInstead, you might feel numb, cynical, angry, hungry, like you need to look at your phone, sexually aroused, like you need to make plans, sleepy, dissociated, or you might even think that what you're doing is stupid. Those are not failures, they are you experiencing what is often a very charming protector or guard.\n\nOne important voice to become aware of when approaching your inner child is your inherited parent. This is the voice of your parent(s) that you internalized as a child, based on how they treated you. This is not the same as your inner adult (Nurturer, Protector, Leader/Guru) that you will eventually build up. Often this inherited parent acts as a critic or warden, telling your inner child not to cry, not to be \u201cneedy\u201d, not to embarrass them, not to be too independent, etc. So when you begin talking to your child in a new, loving way, this voice may jump in to say that what you\u2019re doing is \u201cfake\u201d.\n\n(\u201cI notice you and what you are trying to do. I want to know more. Could I ask you what you are afraid would happen if you stopped protecting me by\u2026..?)\n\nIf necessary take time and listen. (Perhaps they are afraid that you will lie to yourself again or pretend again or that it will be too painful or you will get spiritual bypass again or you will forgive someone who shouldn\u2019t be forgiven yet or you will see what you want to see or that you will leave them hanging after the session or\u2026..)\n\n(Now talk to the protector. Tell them that it makes sense that they want to protect you and that they don\u2019t have to stop protecting you, but that you want to know what could make them trust you 1% more that you can do that.)\n\nMost of the time the protector wants you to do certain things, set boundaries, do whatever you are supposed to do, eat, not text someone, keep a promise, go to sleep, talk to the therapist, admit that you owe someone money, write something down, etc.\n\nProtection that knows when to stop scanning\n\nDo you want to \u201cembody\u201d your Protector? Then you could practice this:\n\n1. orient self (look around, feel the support around you, etc.)\n\n2. assess the situation (know what you know, what you don\u2019t know and check out what you need to)\n\n3. differentiate between actual/real danger, unknown, past or imagined dangers\n\n4. set boundaries (start with one and make it relative to the danger; move, stop, delay, ask, leave, get support, etc.)\n\n5. verify if it is safe enough\n\n6. stand down and rest\n\nThis seems to me like a \u201cmature\u201d Protector. One that is not afraid to say that he doesn\u2019t know, or one that can ask another human being, or one that can delay interpreting a situation or one that can use a no-trance method. I am learning to \u201cdo\u201d discernment when I need to and stop scanning the room when it isn\u2019t needed anymore.\n\nInner child reparenting\n\nI see a lot of connection between reparenting therapy and self hypnosis. They fit well together. When you go into hypnosis the child might come to you. You might see that child in any form. It can be an image, a posture, a voice, a memory, an emotion, etc. It can be any age. It can be any vulnerable part of you. It doesn\u2019t even have to be a \u201cchild\u201d, if there is no child there, just work with a protector or whatever you find.\n\nDon\u2019t rush the repair\n\nJust be with the child.\n\nIf you can, tell the child that you are there for them and that they don\u2019t have to explain themselves, or be \u201chealed\u201d or impress you. Just tell you what they need to not be alone anymore.\n\nIt can be anything. What does the child need? warmth, to play, to be protected, to mourn, to be angry, food, rest, boundaries, better relationships, to stop fantasizing, to stop working their butt off, that you keep a promise to them for one day, etc. etc.\n\nDon't rush it.\n\nFind a younger you/protector/feeling/signal that comes up in your body, and\n\nA. Prepare yourself to tend to them (get yourself into a place where you can spend time with them, have privacy, feel you can access support if you need it, and be as adult as you can be).\n\nB. Look at what's there before judging or deciding what it is.\n\nC. Ask them what you can do or if you can move closer to them. If you feel like you already know what they need, ask if they'd prefer warmth, space, verbal reassurance, silence, distance, whatever.\n\nD. Give them what you can- don't feel like you have to fix it all.\n\nE. Give yourself some time to let what you did sink in- it may take some time, it may take you to go to sleep, etc.\n\nF. Reconnect with them- don't expect them to merge, go away, forgive you, become happy, etc. Just reconnect with them if they're willing.\n\nG. Rest, and reconnect with them later to see what was helpful.\n\nRemember the goal isn't to make yourself good as new but to make yourself good as you- more supported and connected to yourself. Feel free to modify this as needed, and if you don't like the idea of part work or it makes you feel more divided, you can substitute whatever part you're working with for a signal or a feeling, or an imaginary younger you that you feel embodies the issue you're having.\n\nPlay and rest still need an adult present\n\nWhen you're reparenting, it's okay to play with things that interest your younger states. Whether that means touching things of different textures, drawing, exercising, roleplaying with a plushie in a different voice, etc. As long as you're reality testing is good and you remember that you aren't a child or pet or doll or whatever and that nobody owns you, it's okay to work on getting your play ability back.\n\nNow, before you get to resting, it\u2019s okay to limit the amount of decisions you are going to be making for a certain amount of time, it\u2019s okay to put the things you might not get to on a list and it\u2019s okay to let your inner adult keep watch for a while, and you can still move, stop and come back.\n\nNon-dominant hand dialogue\n\nIf talking out loud or visualizing conversations feels fake, try writing it out. Tell your child/ protector part to write with your nondominant hand, and talk to them with your dominant. It might be a little hard to write with your nondominant hand but you can kind of do it. So for example, they might say \"I don't trust you\" with your nondominant hand, and you can say with your dominant hand \"I know you don't trust me right now but I love you and I want to know how I've fucked up. I don't expect you to trust me but I want to hear you out and give you a promise I can keep today\" and they can say \"what promise?\" and you can say \"I'm going to make sure I eat today/ clear off my desk/ not text so-and-so\"", "f330979231092ffe21d2c05e4f3e24274c978cd8e7628e66a18e01e876e82587"], ["HG14-s-p5+next", () => "For that starting point, I have developed a kind of provisional bridge that I call \u201cborrowed adulthood.\u201d It is important to note here that I\u2019m not suggesting that all of the steps in this process have been formally tested and proven.\n\nAccess your witnessing position if necessary, just noticing what\u2019s there, without needing it to be warm or wise or certain. If you already know how to access different internal positions, move immediately to accessing the adult position you want to borrow.", "9abfda62bf1f7dd20f96d506b76ccc0fcb4e8ed7fb2c7ed84d9391dd90c4b0e8"], ["HG14-s-p7", () => "If you have a safe adult in your life you can borrow from them, if not borrow from a mentor, older brother/sister, imagine your future self, your god/goddess or higher power, a value you have, a plan you have written, etc. It\u2019s ok to just borrow what you need right now, warmth or a boundary or direction, just like you would borrow a cup of sugar from a neighbor.", "c3cb7fdf28c0f350aa896f1362884ae2c7f450830f0a3d0e09cee44d89fba3a9"], ["HG14-s-p8+next", () => "Next, put on your adult hat as if you are an apprentice adult and do or say what you think you should do or say. You should do at least part of what you think you should do or say.\n\n- Return the adult hat, noticing what you borrowed and what you were able to do on your own (even if it\u2019s only 5%).", "23c6b26e416baadb4daa6eb08fa805c3d4bcbc6cccdc1f1afe8f16b87e16c0b5"], ["HG14-s-p16+next", () => "What if the \"child\" doesn't believe you love him/her? It is possible to love him/her even if he/she doesn't believe you love him/her. It is possible for trust to question your promises, remember when you failed to protect him/her, and take it's time.\n\nYou could say something like, \"Okay. I believe that you don't believe me. But I still love you. And you don't have to love me. Please tell me what is not okay.\"", "1977c9bade400179886b9e85b997b3d03461b68007be2a6212e018239c247240"], ["HG14-s-p42+next", () => "If you're not careful, you might find yourself expecting that when you go within to meet your inner child, you'll find your inner child.\n\nInstead, you might feel numb, cynical, angry, hungry, like you need to look at your phone, sexually aroused, like you need to make plans, sleepy, dissociated, or you might even think that what you're doing is stupid. Those are not failures, they are you experiencing what is often a very charming protector or guard.", "36599025b2e6c79cb8ca79036b77532d27691db194474ba1f8b38940a01b5704"], ["HG14-s-p43", () => "Instead, you might feel numb, cynical, angry, hungry, like you need to look at your phone, sexually aroused, like you need to make plans, sleepy, dissociated, or you might even think that what you're doing is stupid. Those are not failures, they are you experiencing what is often a very charming protector or guard.", "676f0b64742a3af1043ec01d3a5c29c8f795676dee709b1ab6e16f85edb5e1d5"], ["HG14-s-p72", () => "Now, before you get to resting, it\u2019s okay to limit the amount of decisions you are going to be making for a certain amount of time, it\u2019s okay to put the things you might not get to on a list and it\u2019s okay to let your inner adult keep watch for a while, and you can still move, stop and come back.", "c40afa3468b4af37b8772e9d400cdcddd3206d7bd88fc8abc8b23a62f841a036"], ["HG15-smp", () => "When \u201cyour voice\u201d is everybody else\u2019s voice\n\nIt can be difficult to connect with your inner child if your inner child didn\u2019t have the opportunity to develop. This happens often when you grow up in a situation where you don\u2019t have a private self, for example when your family, religion, or community \u2018takes over\u2019 very early in your life. Or you are pushed to achieve very early in life. The result is that you don\u2019t know what you feel, what you want, what you believe, what you like and dislike until you have heard someone else\u2019s opinion about it. If you are in that situation, it can be difficult to follow the advice to \u2018love yourself\u2019. You don\u2019t even know who \u2018yourself\u2019 is! So you can do reparenting and finding yourself in parallel. For others, it is very easy to work with the inner child, they can feel it easily.\n\nYou are in this camp if:\n\nYou don\u2019t know what you want, until you have heard what someone else wants.\n\nYour opinion is very different when you are with different people\n\nYou agree with people at the moment but when you are by yourself you realize that you don\u2019t agree with them\n\nYou take responsibility for the emotions of others, at the expense of yourself\n\nWhen you try to love yourself, it feels more like a show\n\nWhen you try to find out how your inner child feels, you feel that you are guessing instead of feeling\n\nYou can rebel, but you can\u2019t choose\n\nOne way of explaining this is that in your childhood you didn\u2019t spend enough attention in finding out what you like and what you want to try out and who you are when nobody is grading you. You were too occupied in not being in pain, reading out what was dangerous and what you had to do to stay in a good bond, etc. This is not about a specific place in your brain, but a way of looking at it.\n\nTemporary Separation. Sometimes it may be wise to remove yourself, for a time, from the people or group that you normally would get answers from. Not for too long, however, or you\u2019ll defeat the purpose of the exercise. You want to let your quieter preferences bubble up to the surface so you can be sure you\u2019re not just echoing your social group.\n\nWhat is the difference between a human doer and a human being? If you don\u2019t feel good enough as a human being, you will try to become good enough as a human doer by for example being beautiful, doing something well, being smart, having a certain status, being spiritual, etc. Those can all be real gifts. They become a bargain for belonging when failing in these areas feels like losing yourself.\n\nSo in order to find yourself, you can ask yourself:\n\nWhat do I like when nobody is looking?\n\nWhat do I believe when I don\u2019t check with other people?\n\nWhat do I want that is neither in rebellion nor in compliance with others?\n\nWhere am I buying my sense of belonging at the expense of betraying myself?\n\nIn what arena am I trying to buy my sense of belonging?\n\nWhat can I try on that I don\u2019t need to be good at?\n\nWith whom can I be myself?\n\nWhat do I feel in my body and what do I make out of it?\n\nGive your inner child the opportunity to do something that has no value on its own and that it doesn\u2019t need to be good at for its resume. For example painting, dancing, gardening, learning a language, playing a sport, doing volunteer work, playing a musical instrument, etc. Because often your inner parent tells your inner child that it is supposed to be good at something as soon as it starts doing it. And that\u2019s not good because your inner child will get humiliated that it isn\u2019t good at it. The adult in you can answer, \u201cWe\u2019re finding out whether we enjoy this, not proving our worth.\u201d So try things out long enough until the humiliation is gone.\n\nWhen you are a child you feel that you need to belong to the family in order to survive. This is why people do things for their family, religion, romantic partner, political tribe, spiritual group, institution, online community etc., that they wouldn\u2019t otherwise do. Part of adulting is working out where you are selling yourself in order to belong and choosing your own ground, and finding out you can disappoint someone and not disappear. A large part of your subconscious mind is made out of other people. That is why you are reading a self hypnosis guide!\n\nWhere am I betraying myself in order to belong?\n\nWhat does it feel like to belong without betraying myself?\n\nWhere do I think I am following my own guidance, but I am in fact following my belonging program?\n\nWhere do I think I am doing things out of love, but I am actually doing it out of fear of not belonging?\n\nWhere do I think I am listening to my conscience, but I am actually listening to my conditioning?\n\nWhere do I think I am doing something out of devotion, but I am actually doing it out of compliance?\n\nWhere do I think I am free, but I am actually rebelling?\n\nAnd then look what your body tells you. It is not always correct, but it is a good place to start.", "51f74a6139a9d03bcc2b9188751bf52ff8e2ba1e3d7ed720076b8dbd1b863969"], ["HG15-s-p9+next", () => "You can rebel, but you can\u2019t choose\n\nOne way of explaining this is that in your childhood you didn\u2019t spend enough attention in finding out what you like and what you want to try out and who you are when nobody is grading you. You were too occupied in not being in pain, reading out what was dangerous and what you had to do to stay in a good bond, etc. This is not about a specific place in your brain, but a way of looking at it.", "f4f986bd5ae041c522049999640d239cad43f0988514d611bdda560c1b4d8569"], ["HG15-s-p10", () => "One way of explaining this is that in your childhood you didn\u2019t spend enough attention in finding out what you like and what you want to try out and who you are when nobody is grading you. You were too occupied in not being in pain, reading out what was dangerous and what you had to do to stay in a good bond, etc. This is not about a specific place in your brain, but a way of looking at it.", "f5cbc4a1e1e9a1b69ba432d8f6f95361355dc88b5f73cb9eca0e247a675b1628"], ["HG15-s-p11", () => "Temporary Separation. Sometimes it may be wise to remove yourself, for a time, from the people or group that you normally would get answers from. Not for too long, however, or you\u2019ll defeat the purpose of the exercise. You want to let your quieter preferences bubble up to the surface so you can be sure you\u2019re not just echoing your social group.", "c4d0b875be3a204d5ecf547cadf2581e044e72fb8988a265db7e24ec1d201b36"], ["HG15-s-p23", () => "When you are a child you feel that you need to belong to the family in order to survive. This is why people do things for their family, religion, romantic partner, political tribe, spiritual group, institution, online community etc., that they wouldn\u2019t otherwise do. Part of adulting is working out where you are selling yourself in order to belong and choosing your own ground, and finding out you can disappoint someone and not disappear. A large part of your subconscious mind is made out of other people. That is why you are reading a self hypnosis guide!", "f61b2359314710e798bb2954671dac32e1d95b93d4ef4442d6ff99581e86f3c9"], ["HG15-s-p24+prev", () => "When you are a child you feel that you need to belong to the family in order to survive. This is why people do things for their family, religion, romantic partner, political tribe, spiritual group, institution, online community etc., that they wouldn\u2019t otherwise do. Part of adulting is working out where you are selling yourself in order to belong and choosing your own ground, and finding out you can disappoint someone and not disappear. A large part of your subconscious mind is made out of other people. That is why you are reading a self hypnosis guide!\n\nWhere am I betraying myself in order to belong?", "fd4d51b8bc60546f46932a3abcd6ce6e9d953279a94e420e5b7316791d856c71"], ["HG24-smp", () => "Troubleshooting\n\nNothing happens\n\nTry starting a bit smaller?\n\nCan you show me a single sensation in the body? Can you show me a single word? Can you show me whether to listen or rest today?\n\nIt feels fake\n\nDo you know what feels fake: the wording, the image, the expectation, or the role? Just because you don't have an inner voice/image doing this, it doesn't mean you are missing an adult capacity or resisting doing the work. If you feel that something is asking you to do something that you do not want to do, then correct it. If you feel that a part might be protecting you from this, then talk to it.\n\n\u201cWhat are you protecting me from?\u201d or \u201cAre you afraid I will lie to myself again?\u201d or \u201cAre you afraid this will just be a performance?\u201d\n\nIt could be an inner voice of a parent you are picking up that is enforcing a rule about how you should be to belong, if so don\u2019t argue with it, find out what rule it is enforcing and then work on finding ordinary evidence that would make your new adult voice more believable.\n\nIf the fake feeling means a needed adult capacity is not there yet, stop trying to believe an inner voice. If you have enough observing ego, borrow whatever you need - warmth, boundary, direction etc - from someone who you can imagine is good enough, maybe a family member, a friend or a famous person. Try out something which rings true, a sentence, an action etc and see how it goes.\n\nThe subconscious will not answer\n\nThere may not be an answer. There may not be an answer that will help you. You may need to try asking a different question or you may just need to rest or finish your inner work for the day. If trust is actually a concern, you can try asking your subconscious \u201cWhat would you need to know in order to trust me?\u201d Some examples of answers might be \u201cI need to know you will set boundaries\u201d \u201cI need to know you will do what you said you will do\u201d \u201cI need to know you won\u2019t keep leaving\u201d \u201cI need to know you won\u2019t think that knowing something means that you don\u2019t need to do anything about it\u201d etc.\n\nThe inner child will not appear\n\nIf you can figure out who the guard is, talk to it. If you can\u2019t, just work with what you are aware of. You can say to the guard \u201cYou don\u2019t have to let me in, just tell me what I need to do to make it safe\u201d. Even if there isn\u2019t a child part that you can talk to, you can work with whatever you are aware of. You can work on your preferences or something that you\u2019re curious about or something that you\u2019re willing to try as a beginner etc. and see how it goes. Work on developing a sense of who you are and reparent yourself as best you can.\n\nYou get anxious\n\nFind out if the anxiety is bad enough that you want to decrease contact with it or if you can manage it and let it continue. If the anxiety is getting too bad, then you need to stop searching for content and help your body first, like the following:\n\n-Where are your feet? Where are you sitting? Focus on your body, your breathing, and the room around you.\n\n-Tell your Little parts and Protector parts that you\u2019re there for your Little parts and that you recognize that your Protector parts are trying to protect you and that you don\u2019t need them to scream at you in order for you to know that something is wrong. Ask them if they need you to do something and if they do, ask them to show you one step at a time that you can do. If they don\u2019t, then ask them to let your body calm down.\n\nIf you\u2019re having chest pain, fainting, suicidal thoughts, psychosis-like symptoms, mania-like symptoms, severe dissociative symptoms, not being able to sleep, wanting to hurt yourself or somebody else, etc. then you need to get professional help. For more on handling anxiety, see the toolbox in Appendix D.\n\nYou dissociate or feel unreal\n\nOpen your eyes, move around, feel something textured, name 5 things that you can see, and end your work for the day.\n\nYou become grandiose\n\nGo eat, go to sleep, do some chores, accept some humility, find somebody to disagree with you, etc.\n\nWhat do you say to yourself in that moment? \u201cIf it\u2019s really there, it\u2019ll still be here after a good night\u2019s sleep, some food, some time, etc, and some subsequent humility, feedback, etc, etc.\u201d\n\nYou become too analytical\n\nYou\u2019re being too analytical. \u201cWhat if you didn\u2019t try to improve it?\u201d Put your hand on your heart, your other on your solar plexis, and say, \u201cI don\u2019t have to do this perfectly. I\u2019m here for a relationship with something deeper than my surface mind.\u201d \u201cWhat can you do to make this a communion, not a performance?\u201d Maybe it\u2019s silence, resting, or doing something. Whatever it is, just do it.\n\nYou become too blissful or diffuse\n\nYou\u2019re being too blissful, diffuse, etc. Bring it down to a more specific level. \u201cWhat\u2019s the smallest, most specific thing you can do to demonstrate the love you\u2019re feeling?\u201d\n\nYou want the hidden truth immediately\n\nDon\u2019t pry.\n\n\u201cShow me the capacity before the content.\u201d\n\nYou keep daydreaming\n\nYou\u2019re daydreaming. Sit up and open your eyes, and ask yourself, \u201cWhat are you avoiding doing in the real world by doing this?\u201d\n\nYou get stuck in spiritual bypass\n\n\u201cWhere has divine love not yet descended into the wound?\u201d\n\nMaybe you had a profound opening that showed you how much more love and freedom is possible. Let that matter, but don\u2019t demand that the child receive it on command. Maybe when you prayed it seemed like you were being abandoned and condemned. Maybe you felt betrayed by a spiritual teacher. It may be worth exploring these, but you might not want to do more of the same.\n\nSometimes it\u2019s best to get some practical help while life still feels too small, and let yourself be curious about finding more happiness, without necessarily believing the explanation of how it\u2019s going to work. Sometimes people have enough love and meaning to just live their lives, and trying to be spiritual doesn\u2019t have to be another assignment.\n\nYou get stuck in endless processing\n\nYou may have a real wound that needs to be dealt with, but it\u2019s possible you\u2019re caught in a checking loop. Consider asking yourself \u201cWill processing this again actually help me feel, understand, decide, or do something differently? Or is this a form of checking to see if I can get the reassurance that something is finally okay?\u201d Sometimes, whether you\u2019re grieving or doing your practice, it\u2019s okay to cover the same ground again and again.\n\nBut if you think you\u2019re in a checking loop, let the thought be there without arguing with it or trying to make it go away, and then go back to whatever you\u2019ve chosen to do. It\u2019s not necessary to hold a meeting with every thought that comes up, or to do a certain ritual before your life can begin.\n\nWhat would the Leader choose to do now?\n\nYou keep using hypnosis but not changing life\n\nYou\u2019re doing hypnosis over and over again without making changes in your life. Ask yourself, \u201cWhat can I do to show my kid I\u2019m for real?\u201d Then go do it.", "352181efe0cfcb3fff88a8a88fac4f29c34cd8032d81161ad73d7ca74db708c6"], ["HG24-s-p1+next", () => "Try starting a bit smaller?\n\nCan you show me a single sensation in the body? Can you show me a single word? Can you show me whether to listen or rest today?\n\nIt feels fake\n\nDo you know what feels fake: the wording, the image, the expectation, or the role? Just because you don't have an inner voice/image doing this, it doesn't mean you are missing an adult capacity or resisting doing the work. If you feel that something is asking you to do something that you do not want to do, then correct it. If you feel that a part might be protecting you from this, then talk to it.", "7dc91d48b1d6794a9ea8f7dd1376cc628e43c4cd2d96dc20b23dc59962e4ad11"], ["HG24-s-p2+next", () => "Can you show me a single sensation in the body? Can you show me a single word? Can you show me whether to listen or rest today?\n\nIt feels fake\n\nDo you know what feels fake: the wording, the image, the expectation, or the role? Just because you don't have an inner voice/image doing this, it doesn't mean you are missing an adult capacity or resisting doing the work. If you feel that something is asking you to do something that you do not want to do, then correct it. If you feel that a part might be protecting you from this, then talk to it.", "f9c05cfe30969018fa366b33fd94aac498862b462ef0435b08fd42a52a0ea659"], ["HG24-s-p3", () => "Do you know what feels fake: the wording, the image, the expectation, or the role? Just because you don't have an inner voice/image doing this, it doesn't mean you are missing an adult capacity or resisting doing the work. If you feel that something is asking you to do something that you do not want to do, then correct it. If you feel that a part might be protecting you from this, then talk to it.", "5e9cfda6d80dfbb37e34ad3f9d5e10a5fba9ebffda7b7630ae3c4c909eb1b577"], ["HG24-s-p4+next", () => "\u201cWhat are you protecting me from?\u201d or \u201cAre you afraid I will lie to myself again?\u201d or \u201cAre you afraid this will just be a performance?\u201d\n\nIt could be an inner voice of a parent you are picking up that is enforcing a rule about how you should be to belong, if so don\u2019t argue with it, find out what rule it is enforcing and then work on finding ordinary evidence that would make your new adult voice more believable.", "31a3109e69bdb6b5b578e00063d3576aa3d44d590f4212f4e743bcb5fbca4b75"], ["HG24-s-p5", () => "It could be an inner voice of a parent you are picking up that is enforcing a rule about how you should be to belong, if so don\u2019t argue with it, find out what rule it is enforcing and then work on finding ordinary evidence that would make your new adult voice more believable.", "fccfed4f8e7703caf31dc2557c899373a503d814c60b2d78b412549e3502d8c7"], ["HG24-s-p6", () => "If the fake feeling means a needed adult capacity is not there yet, stop trying to believe an inner voice. If you have enough observing ego, borrow whatever you need - warmth, boundary, direction etc - from someone who you can imagine is good enough, maybe a family member, a friend or a famous person. Try out something which rings true, a sentence, an action etc and see how it goes.", "9e321e169e22ddb1e130d255d88f4b0c8fec3fe86f35ca8acc52f96b85a4f2cd"], ["HG24-s-p7", () => "There may not be an answer. There may not be an answer that will help you. You may need to try asking a different question or you may just need to rest or finish your inner work for the day. If trust is actually a concern, you can try asking your subconscious \u201cWhat would you need to know in order to trust me?\u201d Some examples of answers might be \u201cI need to know you will set boundaries\u201d \u201cI need to know you will do what you said you will do\u201d \u201cI need to know you won\u2019t keep leaving\u201d \u201cI need to know you won\u2019t think that knowing something means that you don\u2019t need to do anything about it\u201d etc.", "a9cee192979c04e0840d77f43ac30344eefeb71e2a56a082b8f319110f732cab"], ["HG24-s-p8", () => "If you can figure out who the guard is, talk to it. If you can\u2019t, just work with what you are aware of. You can say to the guard \u201cYou don\u2019t have to let me in, just tell me what I need to do to make it safe\u201d. Even if there isn\u2019t a child part that you can talk to, you can work with whatever you are aware of. You can work on your preferences or something that you\u2019re curious about or something that you\u2019re willing to try as a beginner etc. and see how it goes. Work on developing a sense of who you are and reparent yourself as best you can.", "74b169248879d5be5840eb0847f12383a235d673e4e0f5869fd075d67b787260"], ["HG24-s-p9+next", () => "Find out if the anxiety is bad enough that you want to decrease contact with it or if you can manage it and let it continue. If the anxiety is getting too bad, then you need to stop searching for content and help your body first, like the following:\n\n-Where are your feet? Where are you sitting? Focus on your body, your breathing, and the room around you.", "4a7970fca05cf3a56323e88463494d326013ffbe59252383043956c0116a34ed"], ["HG24-s-p11", () => "-Tell your Little parts and Protector parts that you\u2019re there for your Little parts and that you recognize that your Protector parts are trying to protect you and that you don\u2019t need them to scream at you in order for you to know that something is wrong. Ask them if they need you to do something and if they do, ask them to show you one step at a time that you can do. If they don\u2019t, then ask them to let your body calm down.", "48212968b97728d5e20d5f0321b494a542e65dc24fdbb877bc98c99506a789bb"], ["HG24-s-p12+prev", () => "-Tell your Little parts and Protector parts that you\u2019re there for your Little parts and that you recognize that your Protector parts are trying to protect you and that you don\u2019t need them to scream at you in order for you to know that something is wrong. Ask them if they need you to do something and if they do, ask them to show you one step at a time that you can do. If they don\u2019t, then ask them to let your body calm down.\n\nIf you\u2019re having chest pain, fainting, suicidal thoughts, psychosis-like symptoms, mania-like symptoms, severe dissociative symptoms, not being able to sleep, wanting to hurt yourself or somebody else, etc. then you need to get professional help. For more on handling anxiety, see the toolbox in Appendix D.", "a27e61a1746afdc5097a2547735e229249fa055a9e64efe8904d37b8431d9875"], ["HG24-s-p13+prev", () => "If you\u2019re having chest pain, fainting, suicidal thoughts, psychosis-like symptoms, mania-like symptoms, severe dissociative symptoms, not being able to sleep, wanting to hurt yourself or somebody else, etc. then you need to get professional help. For more on handling anxiety, see the toolbox in Appendix D.\n\nYou dissociate or feel unreal\n\nOpen your eyes, move around, feel something textured, name 5 things that you can see, and end your work for the day.", "74aac2a3bc082bbd8c45387fd778ea7824628c9be201c38192d6a7a9a8f7f0cf"], ["HG24-s-p14+next", () => "Go eat, go to sleep, do some chores, accept some humility, find somebody to disagree with you, etc.\n\nWhat do you say to yourself in that moment? \u201cIf it\u2019s really there, it\u2019ll still be here after a good night\u2019s sleep, some food, some time, etc, and some subsequent humility, feedback, etc, etc.\u201d", "6ca179e2268f4977f55a8a630765e0836bb621d77b458a112e14b6cb88395274"], ["HG24-s-p16", () => "You\u2019re being too analytical. \u201cWhat if you didn\u2019t try to improve it?\u201d Put your hand on your heart, your other on your solar plexis, and say, \u201cI don\u2019t have to do this perfectly. I\u2019m here for a relationship with something deeper than my surface mind.\u201d \u201cWhat can you do to make this a communion, not a performance?\u201d Maybe it\u2019s silence, resting, or doing something. Whatever it is, just do it.", "c520ab06e6c2c9588fa5dd40dbd5d398eeef593e58753aa18d0bb66d8fcaf829"], ["HG24-s-p17+next", () => "You\u2019re being too blissful, diffuse, etc. Bring it down to a more specific level. \u201cWhat\u2019s the smallest, most specific thing you can do to demonstrate the love you\u2019re feeling?\u201d\n\nYou want the hidden truth immediately\n\nDon\u2019t pry.\n\n\u201cShow me the capacity before the content.\u201d\n\nYou keep daydreaming\n\nYou\u2019re daydreaming. Sit up and open your eyes, and ask yourself, \u201cWhat are you avoiding doing in the real world by doing this?\u201d", "1ef86d01376d0df2ca6e73ccfff53795ac355d4adcaaa67ca150b45279e7efd6"], ["HG24-s-p21+next", () => "\u201cWhere has divine love not yet descended into the wound?\u201d\n\nMaybe you had a profound opening that showed you how much more love and freedom is possible. Let that matter, but don\u2019t demand that the child receive it on command. Maybe when you prayed it seemed like you were being abandoned and condemned. Maybe you felt betrayed by a spiritual teacher. It may be worth exploring these, but you might not want to do more of the same.", "c7f641a228067f338d363ef52ce3675d6807508fdad0c61f09cf3ac7a387bc7d"], ["HG24-s-p22", () => "Maybe you had a profound opening that showed you how much more love and freedom is possible. Let that matter, but don\u2019t demand that the child receive it on command. Maybe when you prayed it seemed like you were being abandoned and condemned. Maybe you felt betrayed by a spiritual teacher. It may be worth exploring these, but you might not want to do more of the same.", "a59d075fb3ef3df0734422efe1d5ee08fa435a18342269b592544ebff2bc2f21"], ["HG24-s-p23", () => "Sometimes it\u2019s best to get some practical help while life still feels too small, and let yourself be curious about finding more happiness, without necessarily believing the explanation of how it\u2019s going to work. Sometimes people have enough love and meaning to just live their lives, and trying to be spiritual doesn\u2019t have to be another assignment.", "7abdb46f4e97a76f30c3bc50461515d9c96245dd19a25d14202fb7cba34c8a12"], ["HG24-s-p24", () => "You may have a real wound that needs to be dealt with, but it\u2019s possible you\u2019re caught in a checking loop. Consider asking yourself \u201cWill processing this again actually help me feel, understand, decide, or do something differently? Or is this a form of checking to see if I can get the reassurance that something is finally okay?\u201d Sometimes, whether you\u2019re grieving or doing your practice, it\u2019s okay to cover the same ground again and again.", "862709a169b1031863b6180b31e174c6799e7bffe751faec0641908cdc1799ee"], ["HG24-s-p25", () => "But if you think you\u2019re in a checking loop, let the thought be there without arguing with it or trying to make it go away, and then go back to whatever you\u2019ve chosen to do. It\u2019s not necessary to hold a meeting with every thought that comes up, or to do a certain ritual before your life can begin.", "44306f4980fd1894e841bbbc96e0a9f837f1fa99bd3c444e478f9135833d319c"], ["HG24-s-p26+prev", () => "But if you think you\u2019re in a checking loop, let the thought be there without arguing with it or trying to make it go away, and then go back to whatever you\u2019ve chosen to do. It\u2019s not necessary to hold a meeting with every thought that comes up, or to do a certain ritual before your life can begin.\n\nWhat would the Leader choose to do now?", "92cc3066a4ab0b5e7e8478bb0d659ae0affb1e69df7b0280baca543cfedf1ae6"], ["HG24-s-p27+prev", () => "But if you think you\u2019re in a checking loop, let the thought be there without arguing with it or trying to make it go away, and then go back to whatever you\u2019ve chosen to do. It\u2019s not necessary to hold a meeting with every thought that comes up, or to do a certain ritual before your life can begin.\n\nWhat would the Leader choose to do now?\n\nYou keep using hypnosis but not changing life\n\nYou\u2019re doing hypnosis over and over again without making changes in your life. Ask yourself, \u201cWhat can I do to show my kid I\u2019m for real?\u201d Then go do it.", "66adffa42d469e9be0b3a058335f750870c6d9a67faf5f75e41096e5e281712c"], ["HG18-swa", () => "Come all the way back\n\nCome out the way you came in \u2013 so if you floated up \u2013 float back down \u2013 and land in a weight you are comfortable with. If you made yourself smaller \u2013 make yourself bigger again \u2013 if you called up a younger version of yourself or parts of yourself \u2013 let them know you are now whole and in your body and using your adult judgement etc. If you traveled somewhere \u2013 travel back \u2013 make sure you don\u2019t bring anything back that you didn\u2019t mean to.\n\nScript Bring back only what is useful to use now. Everything else put away until needed. Come back to where and when and where and into the body. It is now over. Listen carefully for instructions to go deeper and/or stay in session. If no instructions to do either one, session is over. Live an ordinary life, unless doing something that was talked about doing later.\n\nCount out. 1. Come back in your body, back to your chosen weight. 2. Come back to your normal breathing pattern. 3. Start to become aware of the sounds in the room and you can name where you are in your head. 4. Move some of your fingers and toes and some of your shoulders and your eyes. 5. Open your eyes when you are ready and feel present, normal and clear. Your session is now over.\n\nIn your mind, tell yourself what day it is or what the date is. Look to your left. Look to your right. Look at something near you, and something far away. Feel free to move around a bit, and when you are sure you can do so without falling over, stand up. Make sure you are oriented and alert -- saying 1, 2, 3, etc. does not necessarily mean you are. Take note of anything you may (or may not) need to do as a result of what came up in this session, and proceed to do something normal.\n\nNote: If you are using a recording and it stops for any reason, simply say to yourself that the recording has stopped and the session is over and use the above method of coming out: open your eyes, say where you are, say what day it is, push down with your feet or your hands, move about, look around, etc. and then use the 5 step method. Don\u2019t just sit there waiting for the voice to come back to release you.\n\nIt is all right to let the recording put you to sleep or have you in a quiet resting state if you are using it to go to sleep. However, if it\u2019s a recording for using when you are awake, it should not leave you in a role, with lowered judgement, impaired movement capabilities, blank, with an undefined reset word, invited to stay altered indefinitely, etc.", "1ce1df2872289b18ea25bd818319c0d79c5d86ba7d30b212e1b547e70aa126df"], ["HG18-a-p1", () => "Come out the way you came in \u2013 so if you floated up \u2013 float back down \u2013 and land in a weight you are comfortable with. If you made yourself smaller \u2013 make yourself bigger again \u2013 if you called up a younger version of yourself or parts of yourself \u2013 let them know you are now whole and in your body and using your adult judgement etc. If you traveled somewhere \u2013 travel back \u2013 make sure you don\u2019t bring anything back that you didn\u2019t mean to.", "a725a862364da0f346ded3d7bcd20bdbe3069ad120e22142b3e50afa1bd644d6"], ["HG18-a-p2", () => "Script Bring back only what is useful to use now. Everything else put away until needed. Come back to where and when and where and into the body. It is now over. Listen carefully for instructions to go deeper and/or stay in session. If no instructions to do either one, session is over. Live an ordinary life, unless doing something that was talked about doing later.", "5a9bcf9ea28046327fd4d7cfa1e996b6b414970286aa2eb00c8d90c91b28473c"], ["HG18-a-p3", () => "Count out. 1. Come back in your body, back to your chosen weight. 2. Come back to your normal breathing pattern. 3. Start to become aware of the sounds in the room and you can name where you are in your head. 4. Move some of your fingers and toes and some of your shoulders and your eyes. 5. Open your eyes when you are ready and feel present, normal and clear. Your session is now over.", "853ef6770625043c4c803ef077c69ef9a318ee9d5cfd49869605fd75f968e3dd"], ["HG18-a-p4", () => "In your mind, tell yourself what day it is or what the date is. Look to your left. Look to your right. Look at something near you, and something far away. Feel free to move around a bit, and when you are sure you can do so without falling over, stand up. Make sure you are oriented and alert -- saying 1, 2, 3, etc. does not necessarily mean you are. Take note of anything you may (or may not) need to do as a result of what came up in this session, and proceed to do something normal.", "dcece651d6cc1ae15a8c3e0d233899bb91173efeb4a1338a2f2325836baf5fa2"], ["HG18-a-p5", () => "Note: If you are using a recording and it stops for any reason, simply say to yourself that the recording has stopped and the session is over and use the above method of coming out: open your eyes, say where you are, say what day it is, push down with your feet or your hands, move about, look around, etc. and then use the 5 step method. Don\u2019t just sit there waiting for the voice to come back to release you.", "8837f5e42c31a3b9a621baec7b45b29d1d43320a14d57ffa46356f8b4fc46ae4"], ["HG18-a-p6", () => "It is all right to let the recording put you to sleep or have you in a quiet resting state if you are using it to go to sleep. However, if it\u2019s a recording for using when you are awake, it should not leave you in a role, with lowered judgement, impaired movement capabilities, blank, with an undefined reset word, invited to stay altered indefinitely, etc.", "d148768555b2bbafc4a9d37bd86e29c0390d6021e724b738a2e1cb7291cf84f5"], ["HG18-swb", () => "Come all the way back\n\nExiting a session is always done in reverse to the way you entered it. If you floated or used another method to go down, do the same to get back down and back into your body, weighting yourself as you chose to do when you entered. If you shrunk yourself, grow back to your normal size. If you went to a younger you or other parts of yourself, take a moment to acknowledge that you are now whole, this is your body and that you have the judgement of an adult. If you traveled, return in the same way. Be sure you are only bringing back what you need to bring back.\n\nIt is my intent to bring back with me only those things that I want at the present time. All other things will be put back in their proper place until I am ready to use them. I am now returning to my normal day to day existence with the intention of taking one honest action. All instructions to go deeper and all instructions to continue this session are now over. My only instructions are the ones needed for my ordinary life and/or my next practice.\n\nWhen you are ready, you can count yourself awake, 1, as you come back into your body and you take on the weight that you choose to have, 2, as you come back to your normal breathing pattern, 3, as you become aware of the sounds in the room around you and you know where you are, 4, as you start to move your fingers and toes, your shoulders and eyes and 5, as you open your eyes, feeling totally present in your body, totally normal and clear headed. The session is over.\n\nReminders It may be helpful for you to say something to yourself like, 'It's (day of the week)' or 'Today's date is...' Once your vision is clear, look to your left, then to your right. Look at something close and something far away. Move around a bit before standing up. Don't stand up until you feel that you can do so safely. Make sure you are oriented and alert. Just because you were able to count doesn't mean you are totally alert. Mentally note what, if anything, came up for you in this session and if there is anything you need to do, if not, go about whatever it is you normally do at this time.\n\nA note about coming out of a recording: If the recording suddenly stops, it is best that you immediately say to yourself that the recording has stopped and that the session is over and use the above methods to come out: open your eyes, say where you are, say what day it is, push down with your feet or your hands, move about, look around and then do the 5 step method. Don\u2019t just sit there expecting the voice to come back and release you from the session.\n\nNOTE: If you are using a recording to take you to sleep, then it is all right to let it put you to sleep or leave you in a quiet, resting state. However, any recording that is meant to be used while you are awake should NOT leave you in a role, with lowered judgement, impaired movement capabilities, blank, with an undefined reset word, invited to stay in an altered state indefinitely, etc.", "c2d09026eb887349d35a09af6fdb501a03e588587d417b81592058bd1df6ee16"], ["HG18-b-p1", () => "Exiting a session is always done in reverse to the way you entered it. If you floated or used another method to go down, do the same to get back down and back into your body, weighting yourself as you chose to do when you entered. If you shrunk yourself, grow back to your normal size. If you went to a younger you or other parts of yourself, take a moment to acknowledge that you are now whole, this is your body and that you have the judgement of an adult. If you traveled, return in the same way. Be sure you are only bringing back what you need to bring back.", "5fc2310cf66a0e2139096a9b38e84dc767de7ee0a502136967304e984ead563b"], ["HG18-b-p2", () => "It is my intent to bring back with me only those things that I want at the present time. All other things will be put back in their proper place until I am ready to use them. I am now returning to my normal day to day existence with the intention of taking one honest action. All instructions to go deeper and all instructions to continue this session are now over. My only instructions are the ones needed for my ordinary life and/or my next practice.", "3b9efee5564a28048931756c3a6ce4a325a8a3568767bbd260c41ffee725dde4"], ["HG18-b-p3", () => "When you are ready, you can count yourself awake, 1, as you come back into your body and you take on the weight that you choose to have, 2, as you come back to your normal breathing pattern, 3, as you become aware of the sounds in the room around you and you know where you are, 4, as you start to move your fingers and toes, your shoulders and eyes and 5, as you open your eyes, feeling totally present in your body, totally normal and clear headed. The session is over.", "0387c5fb0ee7b4e4bf0f6bb2148689e98892ae7af572c82e45e5288d3bb6e818"], ["HG18-b-p4", () => "Reminders It may be helpful for you to say something to yourself like, 'It's (day of the week)' or 'Today's date is...' Once your vision is clear, look to your left, then to your right. Look at something close and something far away. Move around a bit before standing up. Don't stand up until you feel that you can do so safely. Make sure you are oriented and alert. Just because you were able to count doesn't mean you are totally alert. Mentally note what, if anything, came up for you in this session and if there is anything you need to do, if not, go about whatever it is you normally do at this time.", "55a8ce6081429a63b4aef896c9494e10460342aef68a94156cb259daba8d2511"], ["HG18-b-p5", () => "A note about coming out of a recording: If the recording suddenly stops, it is best that you immediately say to yourself that the recording has stopped and that the session is over and use the above methods to come out: open your eyes, say where you are, say what day it is, push down with your feet or your hands, move about, look around and then do the 5 step method. Don\u2019t just sit there expecting the voice to come back and release you from the session.", "4cc3832e91d06766d2bbb1d330ebb7e4b0ce911f1ba30b2bb5d858744538ee07"], ["HG18-b-p6", () => "NOTE: If you are using a recording to take you to sleep, then it is all right to let it put you to sleep or leave you in a quiet, resting state. However, any recording that is meant to be used while you are awake should NOT leave you in a role, with lowered judgement, impaired movement capabilities, blank, with an undefined reset word, invited to stay in an altered state indefinitely, etc.", "784f4b37cda63d04e0c485b08cfe52423e8aa39a7a7f473f45617fca6caf2a0b"]];
const rev = !!window.__reverse;
const items = rev ? items0.slice().reverse() : items0;
const order0 = items0.map(x => x[0]);
const lane = k => "B455" + '_' + k;
try { localStorage.removeItem(lane(rev ? 'rev' : 'fwd')); } catch (e) {}
window.__B455 = [];
const log = m => { window.__B455.push(m); try { localStorage.setItem(lane(rev ? 'rev' : 'fwd'), JSON.stringify(window.__B455)); } catch (e) {} };
const other = () => { try { return JSON.parse(localStorage.getItem(lane(rev ? 'fwd' : 'rev')) || '[]').filter(m => / (clicked|taking)$/.test(m)).map(m => order0.indexOf(m.split(':')[0])); } catch (e) { return []; } };
const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
const sha = async t => Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(t)))).map(b => b.toString(16).padStart(2, '0')).join('');
const button = () => [...document.querySelectorAll('button[type=submit]')].find(b => /check for ai/i.test(b.innerText));
const wait = ms => new Promise(r => setTimeout(r, ms));
async function run() {
  for (const [k, mk, want] of items) {
    const o = other(), i = order0.indexOf(k);
    if (o.length && (rev ? i <= Math.max(...o) : i >= Math.min(...o))) { log('stop at ' + k + ': the other tab has the rest'); break; }
    log(k + ': taking');  // claimed before the work, so the other tab never takes it too (turn 65: with a margin
                          // of one instead, both tabs stopped short of the last check)
    const T = mk();  // built when its turn comes, so it can use texts stored earlier in this batch
    for (let j = 0; j < 20 && !(button() && document.querySelector('textarea')); j++) await wait(500);
    const ta = document.querySelector('textarea');
    if (!ta) { log(k + ': no textarea'); break; }
    setter.call(ta, T); ta.dispatchEvent(new Event('input', {bubbles: true}));
    let b = null;
    for (let j = 0; j < 30; j++) { await wait(500); b = button(); if (b && !b.disabled) break; }
    const h = await sha(ta.value);
    if (h !== want) { log(k + ': hash mismatch ' + h + ' (is its prefix in sessionStorage?)'); break; }
    if (!b || b.disabled) { log(k + ': button not ready'); break; }
    try { sessionStorage.setItem(k, T); } catch (e) {}
    b.click(); log(k + ': clicked');
    await wait(10000);
  }
  log('end');
}
run(); 'started'
